// Package memba_weighted_policy implements the approved founding coalition and delay
// rules. The hosting DAO must authenticate callers, classify and freeze typed
// actions, and keep every Policy and Proposal private. This package grants no
// authority over a realm and is not a replacement for those integration gates.
package memba_weighted_policy

import (
	"strings"
	"time"
)

type Category string

const (
	Routine   Category = "routine"
	Financial Category = "financial"
	Critical  Category = "critical"
)

// VotingPeriod is fixed by the approved founding policy, not proposer input.
const VotingPeriod = 7 * 24 * time.Hour

type Vote string

const (
	Yes     Vote = "yes"
	No      Vote = "no"
	Abstain Vote = "abstain"
)

// PersonID is the directory's unique human identity, never a wallet alias.
// The host must establish that different PersonIDs really are different people.
type Member struct {
	PersonID string
	Address  address
	Founder  bool
}

// Policy fixes one founding seven-person roster. Reconfiguration deliberately
// invalidates every pending proposal, including already mature proposals.
// Only a reviewed critical-action handler in the host may call Reconfigure.
type Policy struct {
	members    [7]Member
	generation uint64
}

func New(members []Member) *Policy {
	return &Policy{members: validateRoster(members), generation: 1}
}

func validateRoster(members []Member) [7]Member {
	if len(members) != 7 {
		panic("policy requires seven people")
	}
	var roster [7]Member
	founders := 0
	for i, m := range members {
		if m.PersonID == "" || strings.TrimSpace(m.PersonID) != m.PersonID || !m.Address.IsValid() {
			panic("invalid member identity")
		}
		for j := 0; j < i; j++ {
			if roster[j].PersonID == m.PersonID || roster[j].Address == m.Address {
				panic("duplicate person or address")
			}
		}
		if m.Founder {
			founders++
		}
		roster[i] = m
	}
	if founders != 1 {
		panic("policy requires one founder and six developers")
	}
	return roster
}

// Reconfigure is a host-only operation, not an authenticated public DAO API.
// It preserves the approved seven seats and 2/1 weights. Invalid input cannot
// mutate the roster or invalidate proposals, even if the host recovers a panic.
func (p *Policy) Reconfigure(members []Member) {
	roster := validateRoster(members)
	if p.generation == ^uint64(0) {
		panic("policy generation exhausted")
	}
	p.members = roster
	p.generation++
}

func (p *Policy) memberIndex(who address) int {
	if p.generation == 0 {
		return -1
	}
	for i, m := range p.members {
		if m.Address == who {
			return i
		}
	}
	return -1
}

// MayPause establishes member eligibility only. The host must dispatch only a
// typed, allowlisted pause operation; this is never spend or unpause authority.
func (p *Policy) MayPause(who address) bool { return p.memberIndex(who) >= 0 }

// Proposal freezes the category, exact action bytes and roster generation.
// The host determines the category from the action handler, never user input.
// Each proposal has its own vote storage and qualification clocks.
// yesSince[i] is the start of seat i's current uninterrupted YES ballot and is
// meaningful only while votes[i] is Yes.
type Proposal struct {
	policy         *Policy
	generation     uint64
	category       Category
	action         string
	votes          [7]Vote
	yesSince       [7]time.Time
	createdAt      time.Time
	votingDeadline time.Time
	lastChange     time.Time
	consumed       bool
}

func (p *Policy) NewProposal(category Category, action string) *Proposal {
	if p.generation == 0 {
		panic("uninitialized policy")
	}
	if category != Routine && category != Financial && category != Critical {
		panic("unknown action category")
	}
	if action == "" {
		panic("empty action")
	}
	now := time.Now()
	return &Proposal{policy: p, generation: p.generation, category: category, action: action, createdAt: now, votingDeadline: now.Add(VotingPeriod), lastChange: now}
}

func (p *Proposal) assertActive() {
	if p.consumed || p.generation != p.policy.generation {
		panic("proposal consumed or invalidated")
	}
}

// Vote requires a caller identity already authenticated by the host realm.
// Voting closes at the deadline, including changes to existing ballots.
// A critical route starts when some coalition that is still voting YES without
// interruption first met its threshold. A withdrawal moves the clock only when
// every such coalition needed that ballot, so voters the rest of the YES set
// does not need cannot postpone execution by withdrawing and rejoining.
func (p *Proposal) Vote(who address, vote Vote) {
	p.assertActive()
	i := p.policy.memberIndex(who)
	if i < 0 {
		panic("voter is not a member")
	}
	if vote != Yes && vote != No && vote != Abstain {
		panic("invalid vote")
	}
	now := time.Now()
	if now.Before(p.lastChange) {
		panic("chain time regressed")
	}
	if !now.Before(p.votingDeadline) {
		panic("voting closed")
	}
	if p.votes[i] == vote {
		return
	}
	p.votes[i] = vote
	p.lastChange = now
	if vote == Yes {
		p.yesSince[i] = now
	}
}

// qualifiedSince returns the earliest start of an uninterrupted YES coalition
// meeting the weighted (6 points, 4 people) or developer (5 developers)
// critical threshold, or the zero time when no current coalition qualifies.
// Candidate starts are the seats' own streak starts; the coalition for a
// candidate is every current YES ballot that began no later than it.
func (p *Proposal) qualifiedSince(developersOnly bool) time.Time {
	var earliest time.Time
	for c, candidate := range p.votes {
		if candidate != Yes {
			continue
		}
		start := p.yesSince[c]
		if !earliest.IsZero() && !start.Before(earliest) {
			continue
		}
		weight, people := 0, 0
		for j, vote := range p.votes {
			if vote != Yes || p.yesSince[j].After(start) {
				continue
			}
			founder := p.policy.members[j].Founder
			if developersOnly && founder {
				continue
			}
			people++
			weight++
			if founder {
				weight++
			}
		}
		if developersOnly && people >= 5 || !developersOnly && weight >= 6 && people >= 4 {
			earliest = start
		}
	}
	return earliest
}

func (p *Proposal) tally() (weight, people, developers int) {
	for i, vote := range p.votes {
		if vote != Yes {
			continue
		}
		people++
		weight++
		if p.policy.members[i].Founder {
			weight++
		} else {
			developers++
		}
	}
	return
}

// State is a copy for rendering. Reading never starts or advances a clock.
// An invalidated proposal reports no current tally or execution authorization.
type State struct {
	Category       Category
	CreatedAt      time.Time
	VotingDeadline time.Time
	VotingClosed   bool
	Qualified      bool
	Expired        bool
	WeightYes      int
	PeopleYes      int
	DevelopersYes  int
	WeightedAfter  time.Time
	DeveloperAfter time.Time
	Invalidated    bool
	Consumed       bool
	Ready          bool
}

func (p *Proposal) State() State {
	now := time.Now()
	s := State{Category: p.category, CreatedAt: p.createdAt, VotingDeadline: p.votingDeadline, VotingClosed: !now.Before(p.votingDeadline), Invalidated: p.generation != p.policy.generation, Consumed: p.consumed}
	if s.Invalidated || s.Consumed {
		return s
	}
	s.WeightYes, s.PeopleYes, s.DevelopersYes = p.tally()
	if now.Before(p.lastChange) {
		return s
	}
	switch p.category {
	case Routine:
		s.Qualified = s.WeightYes >= 3 && s.PeopleYes >= 2
		s.Ready = s.Qualified
	case Financial:
		s.Qualified = s.WeightYes >= 5 && s.PeopleYes >= 3
		s.Ready = s.Qualified
	case Critical:
		weightedSince := p.qualifiedSince(false)
		developerSince := p.qualifiedSince(true)
		s.Qualified = !weightedSince.IsZero() || !developerSince.IsZero()
		if !weightedSince.IsZero() {
			s.WeightedAfter = weightedSince.Add(24 * time.Hour)
			s.Ready = !now.Before(s.WeightedAfter)
		}
		if !developerSince.IsZero() {
			s.DeveloperAfter = developerSince.Add(72 * time.Hour)
			s.Ready = s.Ready || !now.Before(s.DeveloperAfter)
		}
	}
	// Ballots are immutable after closing. A pre-deadline qualification can
	// finish its existing delay afterward; an unqualified ballot cannot revive.
	s.Expired = s.VotingClosed && !s.Qualified
	return s
}

// Consume binds execution to the frozen action and marks it consumed BEFORE
// the host invokes its typed handler. The host must let handler failure abort
// the transaction: recovering a panic does not roll back Gno realm state.
// Caller authentication and current-member executor eligibility belong to the
// host. Do not expose Proposal pointers or call Consume from a read endpoint.
func (p *Proposal) Consume(action string) {
	p.assertActive()
	if action != p.action {
		panic("action changed")
	}
	if !p.State().Ready {
		panic("proposal is not ready")
	}
	p.consumed = true
}

package memba_weighted_host

import (
	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
	"strconv"
	"strings"
)

const AppstorePath = "gno.land/r/samcrew/memba_appstore_v3"
const AppstoreMaxFee = int64(100000000)

type AppstoreKind string

const (
	AppstoreAccept        AppstoreKind = "accept-owner"
	AppstoreReturn        AppstoreKind = "return-owner"
	AppstoreAbortReturn   AppstoreKind = "abort-return"
	AppstoreAddCurator    AppstoreKind = "add-curator"
	AppstoreRemoveCurator AppstoreKind = "remove-curator"
	AppstoreFee           AppstoreKind = "set-fee"
	AppstoreTreasury      AppstoreKind = "set-treasury"
	AppstoreUnpause       AppstoreKind = "unpause"
	AppstoreSeal          AppstoreKind = "seal-import"
	AppstoreApprove       AppstoreKind = "approve"
	AppstoreReject        AppstoreKind = "reject"
	AppstoreDelist        AppstoreKind = "delist"
	AppstoreRestore       AppstoreKind = "restore"
	AppstoreClearFlags    AppstoreKind = "clear-flags"
)

type AppstorePolicy struct{ dao, successor, treasury address }

func NewAppstorePolicy(dao, successor, treasury address) AppstorePolicy {
	if dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("appstore policy requires the founding DAO address")
	}
	for _, a := range []address{successor, treasury} {
		if !a.IsValid() || a == dao || a == chain.PackageAddress(AppstorePath) {
			panic("appstore destination must be valid and distinct from DAO and target")
		}
	}
	return AppstorePolicy{dao, successor, treasury}
}
func (p AppstorePolicy) DAO() address       { return p.dao }
func (p AppstorePolicy) Successor() address { return p.successor }
func (p AppstorePolicy) Treasury() address  { return p.treasury }

type AppstoreAction struct {
	kind         AppstoreKind
	recipient    address
	fee          int64
	path, reason string
}

func (p AppstorePolicy) Accept() AppstoreAction { return AppstoreAction{kind: AppstoreAccept} }
func (p AppstorePolicy) Return() AppstoreAction {
	return AppstoreAction{kind: AppstoreReturn, recipient: p.successor}
}
func (p AppstorePolicy) AbortReturn() AppstoreAction {
	return AppstoreAction{kind: AppstoreAbortReturn, recipient: p.successor}
}
func (p AppstorePolicy) SetTreasury() AppstoreAction {
	return AppstoreAction{kind: AppstoreTreasury, recipient: p.treasury}
}
func AppstoreCurator(who address, grant bool) AppstoreAction {
	k := AppstoreRemoveCurator
	if grant {
		k = AppstoreAddCurator
	}
	a := AppstoreAction{kind: k, recipient: who}
	a.Bytes()
	return a
}
func AppstoreRegistrationFee(fee int64) AppstoreAction {
	a := AppstoreAction{kind: AppstoreFee, fee: fee}
	a.Bytes()
	return a
}
func AppstoreResume() AppstoreAction     { return AppstoreAction{kind: AppstoreUnpause} }
func AppstoreSealImport() AppstoreAction { return AppstoreAction{kind: AppstoreSeal} }
func AppstoreModeration(kind AppstoreKind, path, reason string) AppstoreAction {
	a := AppstoreAction{kind: kind, path: path, reason: reason}
	if !a.IsListing() {
		panic("unsupported appstore moderation")
	}
	a.Bytes()
	return a
}
func (a AppstoreAction) Kind() AppstoreKind { return a.kind }
func (a AppstoreAction) Recipient() address { return a.recipient }
func (a AppstoreAction) Fee() int64         { return a.fee }
func (a AppstoreAction) Path() string       { return a.path }
func (a AppstoreAction) Reason() string     { return a.reason }
func (a AppstoreAction) IsListing() bool {
	return a.kind == AppstoreApprove || a.kind == AppstoreReject || a.kind == AppstoreDelist || a.kind == AppstoreRestore || a.kind == AppstoreClearFlags
}
func (a AppstoreAction) Bytes() string {
	if a.IsListing() {
		if a.recipient != "" || a.fee != 0 || len(a.path) > 200 || !(strings.HasPrefix(a.path, "gno.land/r/") || strings.HasPrefix(a.path, "gno.land/p/")) || len(a.reason) > 500 || (a.kind != AppstoreReject && a.reason != "") {
			panic("invalid appstore moderation")
		}
	} else {
		if a.path != "" || a.reason != "" {
			panic("malformed appstore action")
		}
		switch a.kind {
		case AppstoreAccept, AppstoreUnpause, AppstoreSeal:
			if a.recipient != "" || a.fee != 0 {
				panic("malformed appstore action")
			}
		case AppstoreReturn, AppstoreAbortReturn, AppstoreTreasury, AppstoreAddCurator, AppstoreRemoveCurator:
			if !a.recipient.IsValid() || a.fee != 0 {
				panic("invalid appstore recipient")
			}
		case AppstoreFee:
			if a.recipient != "" || a.fee < 0 || a.fee > AppstoreMaxFee {
				panic("invalid appstore fee")
			}
		default:
			panic("unsupported appstore action")
		}
	}
	return "appstore/v1|" + AppstorePath + "|" + quoteJSON(string(a.kind)) + "|" + quoteJSON(string(a.recipient)) + "|" + strconv.FormatInt(a.fee, 10) + "|" + quoteJSON(a.path) + "|" + quoteJSON(a.reason)
}
func (a AppstoreAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	if a.IsListing() {
		return memba_weighted_policy.Routine
	}
	switch a.kind {
	case AppstoreFee, AppstoreTreasury, AppstoreUnpause:
		return memba_weighted_policy.Financial
	}
	return memba_weighted_policy.Critical
}

package memba_weighted_host

import "gno.land/p/samcrew/memba_weighted_policy"

type AppstoreListing struct {
	Exists                      bool
	ContentHash, Status, Reason string
	Credit                      bool
	Flags                       int
	ClearKeys                   string
}
type AppstoreState struct {
	Owner, PendingOwner, Treasury                                              address
	Fee                                                                        int64
	Paused, Sealed, OwnerCurator, DAOCurator, SuccessorCurator, SubjectCurator bool
	Listing                                                                    AppstoreListing
}
type appstoreProposal struct {
	action AppstoreAction
	before AppstoreState
}

func appstoreCommitment(a AppstoreAction, s AppstoreState) string {
	return a.Bytes() + "|before|" + appstoreStateJSON(s)
}
func (h *Host) validateAppstoreAuthority(s AppstoreState) {
	if h.appstorePolicy == nil {
		panic("appstore actions are not configured")
	}
	if !s.Owner.IsValid() || !s.Treasury.IsValid() || (s.PendingOwner != "" && !s.PendingOwner.IsValid()) || s.Fee < 0 || s.Fee > AppstoreMaxFee {
		panic("invalid appstore pre-state")
	}
}
func (h *Host) validateAppstore(a AppstoreAction, s AppstoreState) {
	h.validateAppstoreAuthority(s)
	a.Bytes()
	p := h.appstorePolicy
	if !a.IsListing() && s.Listing != (AppstoreListing{}) {
		panic("unexpected appstore listing state")
	}
	if a.kind != AppstoreAddCurator && a.kind != AppstoreRemoveCurator && s.SubjectCurator {
		panic("unexpected appstore curator state")
	}
	if a.kind == AppstoreAccept {
		if s.Owner == p.DAO() || s.PendingOwner != p.DAO() {
			panic("DAO is not pending appstore owner")
		}
		return
	}
	if s.Owner != p.DAO() {
		panic("DAO is not appstore owner")
	}
	if a.kind == AppstoreAbortReturn {
		if a.recipient != p.Successor() || s.PendingOwner != p.Successor() {
			panic("appstore return does not match policy")
		}
		return
	}
	if s.PendingOwner != "" {
		panic("appstore authority transfer is pending")
	}
	if a.IsListing() {
		l := s.Listing
		if !s.DAOCurator {
			panic("DAO is not appstore curator")
		}
		if !l.Exists || l.ContentHash == "" || l.Flags < 0 {
			panic("invalid appstore listing")
		}
		switch a.kind {
		case AppstoreApprove:
			if l.Status != "pending" && l.Status != "rejected" {
				panic("appstore approval requires pending or rejected listing")
			}
		case AppstoreReject:
			if l.Status != "pending" {
				panic("appstore rejection requires pending listing")
			}
		case AppstoreDelist:
			if l.Status == "delisted" {
				panic("appstore delist is a no-op")
			}
		case AppstoreRestore:
			if l.Status != "delisted" {
				panic("appstore restore requires delisted listing")
			}
		case AppstoreClearFlags:
			if l.Flags <= 0 || l.ClearKeys == "" {
				panic("appstore has no removable flags")
			}
		}
		return
	}
	switch a.kind {
	case AppstoreReturn:
		if a.recipient != p.Successor() {
			panic("appstore successor does not match policy")
		}
	case AppstoreTreasury:
		if a.recipient != p.Treasury() {
			panic("appstore treasury does not match policy")
		}
		if s.Treasury == a.recipient {
			panic("appstore treasury is a no-op")
		}
	case AppstoreFee:
		if s.Fee == a.fee {
			panic("appstore fee is a no-op")
		}
	case AppstoreAddCurator:
		if s.SubjectCurator {
			panic("appstore curator grant is a no-op")
		}
	case AppstoreRemoveCurator:
		if !s.SubjectCurator {
			panic("appstore curator removal is a no-op")
		}
	case AppstoreUnpause:
		if !s.Paused {
			panic("appstore unpause is a no-op")
		}
	case AppstoreSeal:
		if s.Sealed {
			panic("appstore import already sealed")
		}
	default:
		panic("unsupported appstore action")
	}
}
func (h *Host) ProposeAppstore(a AppstoreAction, s AppstoreState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateAppstore(a, s)
	p := &roleProposal{proposer: who, appstore: &appstoreProposal{action: a, before: s}}
	p.ballot = h.policy.NewProposal(a.Category(), appstoreCommitment(a, s))
	h.addProposal(p)
	return uint64(len(h.proposals))
}
func (h *Host) invalidateAppstorePeers(cause string, id uint64) {
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(cause, id, AppstorePath)
}
func (h *Host) ConsumeAppstore(id uint64, s AppstoreState, rlm realm) AppstoreAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.appstore == nil {
		panic("proposal is not an appstore action")
	}
	h.validateAppstore(p.appstore.action, s)
	p.ballot.Consume(appstoreCommitment(p.appstore.action, s))
	h.invalidateAppstorePeers(InvalidatedByExecution, id)
	return p.appstore.action
}
func (h *Host) PrepareAppstoreEmergencyPause(s AppstoreState, rlm realm) {
	assertCaller(h, rlm)
	h.validateAppstoreAuthority(s)
	if s.Owner != h.appstorePolicy.DAO() {
		panic("DAO is not appstore owner")
	}
	if s.Paused {
		panic("appstore is already paused")
	}
	if s.Listing != (AppstoreListing{}) || s.SubjectCurator {
		panic("unexpected appstore pause state")
	}
	h.invalidateAppstorePeers(InvalidatedByPause, 0)
}

package memba_weighted_host

import "strconv"

func (h *Host) appstoreConfigJSON() string {
	if h.appstorePolicy == nil {
		return ""
	}
	return `,"appstorePolicy":{"target":` + quoteJSON(AppstorePath) + `,"successor":` + quoteJSON(string(h.appstorePolicy.Successor())) + `,"treasury":` + quoteJSON(string(h.appstorePolicy.Treasury())) + `,"maxRegistrationFee":"100000000","curatorCategory":"critical","sealCategory":"critical","moderationCategory":"routine","unpauseCategory":"financial","emergencyPause":true,"returnStagesOnly":true,"invalidatesOtherProposals":true}`
}
func appstoreListingJSON(s AppstoreListing) string {
	return `{"exists":` + strconv.FormatBool(s.Exists) + `,"contentHash":` + quoteJSON(s.ContentHash) + `,"status":` + quoteJSON(s.Status) + `,"reason":` + quoteJSON(s.Reason) + `,"credit":` + strconv.FormatBool(s.Credit) + `,"flags":` + quoteJSON(strconv.Itoa(s.Flags)) + `,"clearKeys":` + quoteJSON(s.ClearKeys) + `}`
}
func appstoreStateJSON(s AppstoreState) string {
	return `{"owner":` + quoteJSON(string(s.Owner)) + `,"pendingOwner":` + quoteJSON(string(s.PendingOwner)) + `,"treasury":` + quoteJSON(string(s.Treasury)) + `,"fee":` + quoteJSON(strconv.FormatInt(s.Fee, 10)) + `,"paused":` + strconv.FormatBool(s.Paused) + `,"sealed":` + strconv.FormatBool(s.Sealed) + `,"ownerCurator":` + strconv.FormatBool(s.OwnerCurator) + `,"daoCurator":` + strconv.FormatBool(s.DAOCurator) + `,"successorCurator":` + strconv.FormatBool(s.SuccessorCurator) + `,"subjectCurator":` + strconv.FormatBool(s.SubjectCurator) + `,"listing":` + appstoreListingJSON(s.Listing) + `}`
}
func appstoreActionJSON(a AppstoreAction, s AppstoreState) string {
	return `{"type":"appstore","target":` + quoteJSON(AppstorePath) + `,"operation":` + quoteJSON(string(a.Kind())) + `,"recipient":` + quoteJSON(string(a.Recipient())) + `,"fee":` + quoteJSON(strconv.FormatInt(a.Fee(), 10)) + `,"path":` + quoteJSON(a.Path()) + `,"reason":` + quoteJSON(a.Reason()) + `,"before":` + appstoreStateJSON(s) + `}`
}

package memba_weighted_host

import (
	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
)

const ArcadePath = "gno.land/r/samcrew/memba_arcade_leaderboard_v1"

type ArcadeActionKind string

const (
	ArcadeAcceptOwner    ArcadeActionKind = "accept-owner"
	ArcadeReturnOwner    ArcadeActionKind = "return-owner"
	ArcadeAbortReturn    ArcadeActionKind = "abort-return"
	ArcadeAddAttester    ArcadeActionKind = "add-attester"
	ArcadeRemoveAttester ArcadeActionKind = "remove-attester"
	ArcadeUnpause        ArcadeActionKind = "unpause"
)

type ArcadePolicy struct{ dao, successor address }

func NewArcadePolicy(dao, successor address) ArcadePolicy {
	if !dao.IsValid() || dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("arcade policy requires the founding DAO address")
	}
	if !successor.IsValid() || successor == dao || successor == chain.PackageAddress(ArcadePath) {
		panic("arcade policy requires a valid distinct successor")
	}
	return ArcadePolicy{dao: dao, successor: successor}
}
func (p ArcadePolicy) DAO() address       { return p.dao }
func (p ArcadePolicy) Successor() address { return p.successor }

type ArcadeAction struct {
	kind      ArcadeActionKind
	recipient address
	attester  address
}

func (p ArcadePolicy) Accept() ArcadeAction { return ArcadeAction{kind: ArcadeAcceptOwner} }
func (p ArcadePolicy) Return() ArcadeAction {
	return ArcadeAction{kind: ArcadeReturnOwner, recipient: p.successor}
}
func (p ArcadePolicy) AbortReturn() ArcadeAction {
	return ArcadeAction{kind: ArcadeAbortReturn, recipient: p.successor}
}
func (p ArcadePolicy) AddAttester(who address) ArcadeAction {
	if who == p.DAO() || who == p.Successor() || who == chain.PackageAddress(ArcadePath) {
		panic("arcade attester must be a dedicated external account")
	}
	a := ArcadeAction{kind: ArcadeAddAttester, attester: who}
	a.Bytes()
	return a
}
func ArcadeRevokeAttester(who address) ArcadeAction {
	a := ArcadeAction{kind: ArcadeRemoveAttester, attester: who}
	a.Bytes()
	return a
}
func ArcadeResume() ArcadeAction              { return ArcadeAction{kind: ArcadeUnpause} }
func (a ArcadeAction) Kind() ArcadeActionKind { return a.kind }
func (a ArcadeAction) Recipient() address     { return a.recipient }
func (a ArcadeAction) Attester() address      { return a.attester }
func (a ArcadeAction) Bytes() string {
	base := "arcade/v1|" + ArcadePath + "|" + string(a.kind)
	switch a.kind {
	case ArcadeAcceptOwner, ArcadeUnpause:
		if a.recipient != "" || a.attester != "" {
			panic("malformed arcade action")
		}
		return base
	case ArcadeReturnOwner, ArcadeAbortReturn:
		if !a.recipient.IsValid() || a.attester != "" {
			panic("malformed arcade return action")
		}
		return base + "|" + string(a.recipient)
	case ArcadeAddAttester, ArcadeRemoveAttester:
		if !a.attester.IsValid() || a.recipient != "" {
			panic("invalid arcade attester action")
		}
		return base + "|" + string(a.attester)
	default:
		panic("unsupported arcade action")
	}
}
func (a ArcadeAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	if a.kind == ArcadeUnpause {
		return memba_weighted_policy.Financial
	}
	return memba_weighted_policy.Critical
}

package memba_weighted_host

import "gno.land/p/samcrew/memba_weighted_policy"

// Explicit allowlist bits are separate from the owner's implicit attester right.
type ArcadeState struct {
	Owner, PendingOwner                                            address
	Paused, OwnerListed, DAOListed, SuccessorListed, SubjectListed bool
}
type arcadeProposal struct {
	action ArcadeAction
	before ArcadeState
}

func arcadeCommitment(a ArcadeAction, s ArcadeState) string {
	return a.Bytes() + "|before|" + arcadeStateJSON(s)
}
func (h *Host) validateArcadeAuthority(s ArcadeState) {
	if h.arcadePolicy == nil {
		panic("arcade actions are not configured")
	}
	if !s.Owner.IsValid() || (s.PendingOwner != "" && !s.PendingOwner.IsValid()) {
		panic("invalid arcade authority pre-state")
	}
}
func (h *Host) validateArcade(a ArcadeAction, s ArcadeState) {
	h.validateArcadeAuthority(s)
	a.Bytes()
	p := h.arcadePolicy
	if a.Attester() == "" && s.SubjectListed {
		panic("unexpected arcade subject pre-state")
	}
	if a.Kind() == ArcadeAcceptOwner {
		if s.Owner == p.DAO() || s.PendingOwner != p.DAO() {
			panic("DAO is not pending arcade owner")
		}
		return
	}
	if s.Owner != p.DAO() {
		panic("DAO is not arcade owner")
	}
	if a.Kind() == ArcadeAbortReturn {
		if a.Recipient() != p.Successor() || s.PendingOwner != p.Successor() {
			panic("arcade return does not match policy")
		}
		return
	}
	if s.PendingOwner != "" {
		panic("arcade authority transfer is pending")
	}
	switch a.Kind() {
	case ArcadeReturnOwner:
		if a.Recipient() != p.Successor() {
			panic("arcade successor does not match policy")
		}
	case ArcadeAddAttester:
		p.AddAttester(a.Attester())
		if s.SubjectListed {
			panic("arcade attester grant is a no-op")
		}
	case ArcadeRemoveAttester:
		if !s.SubjectListed {
			panic("arcade attester removal is a no-op")
		}
	case ArcadeUnpause:
		if !s.Paused {
			panic("arcade unpause is a no-op")
		}
	default:
		panic("unsupported arcade action")
	}
}
func (h *Host) ProposeArcade(a ArcadeAction, s ArcadeState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateArcade(a, s)
	p := &roleProposal{proposer: who, arcade: &arcadeProposal{action: a, before: s}}
	p.ballot = h.policy.NewProposal(a.Category(), arcadeCommitment(a, s))
	h.addProposal(p)
	return uint64(len(h.proposals))
}
func (h *Host) invalidateArcadePeers(cause string, id uint64) {
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(cause, id, ArcadePath)
}
func (h *Host) ConsumeArcade(id uint64, s ArcadeState, rlm realm) ArcadeAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.arcade == nil {
		panic("proposal is not an arcade action")
	}
	h.validateArcade(p.arcade.action, s)
	p.ballot.Consume(arcadeCommitment(p.arcade.action, s))
	h.invalidateArcadePeers(InvalidatedByExecution, id)
	return p.arcade.action
}

// A fixed pause-only capability, not a proposal category or a bool-controlled
// escape. An already-paused call cannot invalidate pending unpause approvals.
func (h *Host) PrepareArcadeEmergencyPause(s ArcadeState, rlm realm) {
	assertCaller(h, rlm)
	h.validateArcadeAuthority(s)
	if s.Owner != h.arcadePolicy.DAO() {
		panic("DAO is not arcade owner")
	}
	if s.Paused {
		panic("arcade is already paused")
	}
	if s.SubjectListed {
		panic("unexpected arcade subject pre-state")
	}
	h.invalidateArcadePeers(InvalidatedByPause, 0)
}

