package memba_weighted_host

import (
	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
	"strconv"
)

const EscrowPath = "gno.land/r/samcrew/escrow_v4"

type EscrowActionKind string

const (
	EscrowAcceptOwner   EscrowActionKind = "accept-owner"
	EscrowReturnOwner   EscrowActionKind = "return-owner"
	EscrowAbortReturn   EscrowActionKind = "abort-return"
	EscrowUnpause       EscrowActionKind = "unpause"
	EscrowRefundClient  EscrowActionKind = "refund-client"
	EscrowPayFreelancer EscrowActionKind = "pay-freelancer"
	// EscrowSetFeeRecipient stages a new fallback fee recipient (escrow_v4
	// two-step rotation); the staged address accepts with its own transaction.
	EscrowSetFeeRecipient EscrowActionKind = "set-fee-recipient"
)

type EscrowPolicy struct{ dao, successor address }

func NewEscrowPolicy(dao, successor address) EscrowPolicy {
	if !dao.IsValid() || dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("escrow policy requires the founding DAO address")
	}
	if !successor.IsValid() || successor == dao || successor == chain.PackageAddress(EscrowPath) {
		panic("escrow policy requires a valid distinct successor")
	}
	return EscrowPolicy{dao: dao, successor: successor}
}
func (p EscrowPolicy) DAO() address       { return p.dao }
func (p EscrowPolicy) Successor() address { return p.successor }

type EscrowAction struct {
	kind       EscrowActionKind
	recipient  address
	contractID string
	milestone  int
}

func (p EscrowPolicy) Accept() EscrowAction { return EscrowAction{kind: EscrowAcceptOwner} }
func (p EscrowPolicy) Return() EscrowAction {
	return EscrowAction{kind: EscrowReturnOwner, recipient: p.successor}
}
func (p EscrowPolicy) AbortReturn() EscrowAction {
	return EscrowAction{kind: EscrowAbortReturn, recipient: p.successor}
}
func EscrowResume() EscrowAction { return EscrowAction{kind: EscrowUnpause} }
func EscrowFeeRecipient(recipient address) EscrowAction {
	a := EscrowAction{kind: EscrowSetFeeRecipient, recipient: recipient}
	a.Bytes()
	return a
}
func EscrowResolution(id string, index int, refund bool) EscrowAction {
	kind := EscrowPayFreelancer
	if refund {
		kind = EscrowRefundClient
	}
	a := EscrowAction{kind: kind, contractID: id, milestone: index}
	a.Bytes()
	return a
}
func (a EscrowAction) Kind() EscrowActionKind { return a.kind }
func (a EscrowAction) Recipient() address     { return a.recipient }
func (a EscrowAction) ContractID() string     { return a.contractID }
func (a EscrowAction) Milestone() int         { return a.milestone }
func (a EscrowAction) IsResolution() bool {
	return a.kind == EscrowRefundClient || a.kind == EscrowPayFreelancer
}
func (a EscrowAction) Bytes() string {
	base := "escrow/v1|" + EscrowPath + "|" + string(a.kind)
	if a.IsResolution() {
		n, err := strconv.ParseUint(a.contractID, 10, 64)
		if err != nil || strconv.FormatUint(n, 10) != a.contractID || a.milestone < 0 || a.milestone >= 20 || a.recipient != "" {
			panic("invalid escrow resolution action")
		}
		return base + "|" + a.contractID + "|" + strconv.Itoa(a.milestone)
	}
	if a.contractID != "" || a.milestone != 0 {
		panic("malformed escrow action")
	}
	switch a.kind {
	case EscrowAcceptOwner, EscrowUnpause:
		if a.recipient != "" {
			panic("malformed escrow action")
		}
		return base
	case EscrowReturnOwner, EscrowAbortReturn:
		if !a.recipient.IsValid() {
			panic("invalid escrow return action")
		}
		return base + "|" + string(a.recipient)
	case EscrowSetFeeRecipient:
		if !a.recipient.IsValid() {
			panic("invalid escrow fee recipient action")
		}
		return base + "|" + string(a.recipient)
	default:
		panic("unsupported escrow action")
	}
}
func (a EscrowAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	if a.IsResolution() || a.kind == EscrowUnpause || a.kind == EscrowSetFeeRecipient {
		return memba_weighted_policy.Financial
	}
	return memba_weighted_policy.Critical
}

package memba_weighted_host

import (
	"chain"
	"chain/runtime"
	"gno.land/p/samcrew/memba_weighted_policy"
)

type EscrowMilestone struct {
	ID                                int
	Amount                            int64
	Status                            string
	FundedAt, CompletedAt, DisputedAt int64
	PreDisputeStatus                  string
}
type EscrowContract struct {
	Exists                  bool
	ID, ContentHash, Status string
	Client, Freelancer      address
	Count                   int
	Milestones              [20]EscrowMilestone
}
type EscrowFeeTerms struct {
	RawBPS, EffectiveBPS                             int64
	RawTreasury, FallbackTreasury, EffectiveTreasury address
}
// EscrowState is the escrow_v4 state a proposal freezes. The pause fields copy
// PauseInfo except PausedBlocks, which grows every block. ExitsOpen is also
// height-derived: it is read fresh at proposal and execution time and never
// enters the commitment (escrowStateJSON), so a pause ageing past its blocking
// window cannot make a frozen proposal stale.
type EscrowState struct {
	Owner, PendingOwner               address
	FeeRecipient, PendingFeeRecipient address
	Paused                            bool
	PausedAt, ExitsReopenAt           int64
	CooldownUntil                     int64
	ExitsOpen                         bool
	Contract                          EscrowContract
	Fees                              EscrowFeeTerms
}
type escrowProposal struct {
	action EscrowAction
	before EscrowState
}

func escrowCommitment(a EscrowAction, s EscrowState) string {
	return a.Bytes() + "|before|" + escrowStateJSON(s)
}
func (h *Host) validateEscrowAuthority(s EscrowState) {
	if h.escrowPolicy == nil {
		panic("escrow actions are not configured")
	}
	if !s.Owner.IsValid() || (s.PendingOwner != "" && !s.PendingOwner.IsValid()) || !s.FeeRecipient.IsValid() || (s.PendingFeeRecipient != "" && !s.PendingFeeRecipient.IsValid()) {
		panic("invalid escrow authority pre-state")
	}
	if s.CooldownUntil < 0 || (!s.Paused && (s.PausedAt != 0 || s.ExitsReopenAt != 0 || !s.ExitsOpen)) || (s.Paused && (s.PausedAt <= 0 || s.ExitsReopenAt <= s.PausedAt)) {
		panic("invalid escrow pause pre-state")
	}
}
func (h *Host) validateEscrow(a EscrowAction, s EscrowState) {
	h.validateEscrowAuthority(s)
	a.Bytes()
	p := h.escrowPolicy
	if !a.IsResolution() && (s.Contract != (EscrowContract{}) || s.Fees != (EscrowFeeTerms{})) {
		panic("unexpected escrow dispute pre-state")
	}
	if a.Kind() == EscrowAcceptOwner {
		if s.Owner == p.DAO() || s.PendingOwner != p.DAO() {
			panic("DAO is not pending escrow owner")
		}
		return
	}
	if s.Owner != p.DAO() {
		panic("DAO is not escrow owner")
	}
	if a.Kind() == EscrowAbortReturn {
		if a.Recipient() != p.Successor() || s.PendingOwner != p.Successor() {
			panic("escrow return does not match policy")
		}
		return
	}
	if s.PendingOwner != "" {
		panic("escrow authority transfer is pending")
	}
	switch a.Kind() {
	case EscrowReturnOwner:
		if a.Recipient() != p.Successor() {
			panic("escrow successor does not match policy")
		}
	case EscrowUnpause:
		if !s.Paused {
			panic("escrow unpause is a no-op")
		}
	case EscrowSetFeeRecipient:
		r := a.Recipient()
		if r == p.DAO() || r == chain.PackageAddress(EscrowPath) {
			panic("escrow fee recipient cannot be governance or escrow")
		}
		if r == s.FeeRecipient || r == s.PendingFeeRecipient {
			panic("escrow fee recipient change is a no-op")
		}
	case EscrowRefundClient, EscrowPayFreelancer:
		// escrow_v4 refuses ResolveDispute inside a pause's blocking window;
		// refuse the proposal then too, at creation and again at execution.
		if s.Paused && !s.ExitsOpen {
			panic("escrow exits are paused")
		}
		c := s.Contract
		if !c.Exists || c.ID != a.ContractID() || c.Count < 1 || c.Count > 20 || a.Milestone() >= c.Count || len(c.ContentHash) != 64 || !c.Client.IsValid() {
			panic("invalid escrow contract pre-state")
		}
		for i, m := range c.Milestones {
			if i >= c.Count {
				if m != (EscrowMilestone{}) {
					panic("unexpected escrow milestone pre-state")
				}
				continue
			}
			if m.Amount <= 0 {
				panic("invalid escrow milestone amount")
			}
		}
		m := c.Milestones[a.Milestone()]
		if c.Status != "disputed" || m.Status != "disputed" || (m.PreDisputeStatus != "funded" && m.PreDisputeStatus != "completed") {
			panic("escrow milestone is not disputed")
		}
		if a.Kind() == EscrowRefundClient {
			if c.Client == p.DAO() || c.Client == chain.PackageAddress(EscrowPath) {
				panic("escrow payout cannot be trapped in governance or escrow")
			}
			if s.Fees != (EscrowFeeTerms{}) {
				panic("unexpected escrow refund fee terms")
			}
			return
		}
		if !c.Freelancer.IsValid() || s.Fees.EffectiveBPS < 0 || s.Fees.EffectiveBPS > 500 {
			panic("invalid escrow payout terms")
		}
		if c.Freelancer == p.DAO() || c.Freelancer == chain.PackageAddress(EscrowPath) {
			panic("escrow payout cannot be trapped in governance or escrow")
		}
		fee := (m.Amount/10000)*s.Fees.EffectiveBPS + ((m.Amount%10000)*s.Fees.EffectiveBPS)/10000
		if fee > 0 && (s.Fees.EffectiveTreasury == p.DAO() || s.Fees.EffectiveTreasury == chain.PackageAddress(EscrowPath)) {
			panic("escrow payout cannot be trapped in governance or escrow")
		}
		if fee > 0 && !s.Fees.EffectiveTreasury.IsValid() {
			panic("invalid escrow fee recipient")
		}
	default:
		panic("unsupported escrow action")
	}
}
func (h *Host) ProposeEscrow(a EscrowAction, s EscrowState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateEscrow(a, s)
	p := &roleProposal{proposer: who, escrow: &escrowProposal{action: a, before: s}}
	p.ballot = h.policy.NewProposal(a.Category(), escrowCommitment(a, s))
	h.addProposal(p)
	return uint64(len(h.proposals))
}
func (h *Host) invalidateEscrowPeers(cause string, id uint64) {
	members := []memba_weighted_policy.Member{}
	for _, s := range h.seats {
		members = append(members, s.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(cause, id, EscrowPath)
}
func (h *Host) ConsumeEscrow(id uint64, s EscrowState, rlm realm) EscrowAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.escrow == nil {
		panic("proposal is not an escrow action")
	}
	h.validateEscrow(p.escrow.action, s)
	p.ballot.Consume(escrowCommitment(p.escrow.action, s))
	h.invalidateEscrowPeers(InvalidatedByExecution, id)
	return p.escrow.action
}
func (h *Host) PrepareEscrowEmergencyPause(s EscrowState, rlm realm) {
	assertCaller(h, rlm)
	h.validateEscrowAuthority(s)
	if s.Owner != h.escrowPolicy.DAO() {
		panic("DAO is not escrow owner")
	}
	if s.Paused {
		panic("escrow is already paused")
	}
	// escrow_v4 refuses a Pause before its cooldown ends. Refuse here first,
	// before invalidating any proposal.
	if runtime.ChainHeight() < s.CooldownUntil {
		panic("escrow pause cooldown")
	}
	if s.Contract != (EscrowContract{}) || s.Fees != (EscrowFeeTerms{}) {
		panic("unexpected escrow dispute pre-state")
	}
	h.invalidateEscrowPeers(InvalidatedByPause, 0)
}

package memba_weighted_host

import "strconv"

func (h *Host) escrowConfigJSON() string {
	if h.escrowPolicy == nil {
		return ""
	}
	return `,"escrowPolicy":{"target":` + quoteJSON(EscrowPath) + `,"successor":` + quoteJSON(string(h.escrowPolicy.Successor())) + `,"resolutionCategory":"financial","unpauseCategory":"financial","feeRecipientCategory":"financial","emergencyPause":true,"returnStagesOnly":true,"invalidatesOtherProposals":true}`
}
func escrowNumber(n int64) string { return quoteJSON(strconv.FormatInt(n, 10)) }

// Only dispute actions name a milestone; for the others it is null, so it
// cannot be mistaken for milestone 0.
func escrowMilestoneJSON(a EscrowAction) string {
	if a.Kind() != EscrowRefundClient && a.Kind() != EscrowPayFreelancer {
		return "null"
	}
	return escrowNumber(int64(a.Milestone()))
}
func escrowStateJSON(s EscrowState) string {
	c := s.Contract
	milestones := "["
	for i := 0; i < c.Count; i++ {
		if i > 0 {
			milestones += ","
		}
		m := c.Milestones[i]
		milestones += `{"id":` + escrowNumber(int64(m.ID)) + `,"amount":` + escrowNumber(m.Amount) + `,"status":` + quoteJSON(m.Status) + `,"fundedAt":` + escrowNumber(m.FundedAt) + `,"completedAt":` + escrowNumber(m.CompletedAt) + `,"disputedAt":` + escrowNumber(m.DisputedAt) + `,"preDisputeStatus":` + quoteJSON(m.PreDisputeStatus) + `}`
	}
	milestones += "]"
	return `{"owner":` + quoteJSON(string(s.Owner)) + `,"pendingOwner":` + quoteJSON(string(s.PendingOwner)) + `,"feeRecipient":` + quoteJSON(string(s.FeeRecipient)) + `,"pendingFeeRecipient":` + quoteJSON(string(s.PendingFeeRecipient)) + `,"paused":` + strconv.FormatBool(s.Paused) + `,"pausedAt":` + escrowNumber(s.PausedAt) + `,"exitsReopenAt":` + escrowNumber(s.ExitsReopenAt) + `,"cooldownUntil":` + escrowNumber(s.CooldownUntil) + `,"contract":{"exists":` + strconv.FormatBool(c.Exists) + `,"id":` + quoteJSON(c.ID) + `,"contentHash":` + quoteJSON(c.ContentHash) + `,"status":` + quoteJSON(c.Status) + `,"client":` + quoteJSON(string(c.Client)) + `,"freelancer":` + quoteJSON(string(c.Freelancer)) + `,"count":` + escrowNumber(int64(c.Count)) + `,"milestones":` + milestones + `},"fees":{"rawBPS":` + escrowNumber(s.Fees.RawBPS) + `,"effectiveBPS":` + escrowNumber(s.Fees.EffectiveBPS) + `,"rawTreasury":` + quoteJSON(string(s.Fees.RawTreasury)) + `,"fallbackTreasury":` + quoteJSON(string(s.Fees.FallbackTreasury)) + `,"effectiveTreasury":` + quoteJSON(string(s.Fees.EffectiveTreasury)) + `}}`
}
func escrowActionJSON(a EscrowAction, s EscrowState) string {
	return `{"type":"escrow","target":` + quoteJSON(EscrowPath) + `,"operation":` + quoteJSON(string(a.Kind())) + `,"recipient":` + quoteJSON(string(a.Recipient())) + `,"contractId":` + quoteJSON(a.ContractID()) + `,"milestoneIndex":` + escrowMilestoneJSON(a) + `,"before":` + escrowStateJSON(s) + `}`
}

package memba_weighted_host

import (
	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
)

const FeedPath = "gno.land/r/samcrew/memba_feed_v1"

type FeedActionKind string

const (
	FeedAcceptOwner     FeedActionKind = "accept-owner"
	FeedReturnOwner     FeedActionKind = "return-owner"
	FeedAbortReturn     FeedActionKind = "abort-return"
	FeedAddModerator    FeedActionKind = "add-moderator"
	FeedRemoveModerator FeedActionKind = "remove-moderator"
	FeedUnpause         FeedActionKind = "unpause"
)

type FeedPolicy struct{ dao, successor address }

func NewFeedPolicy(dao, successor address) FeedPolicy {
	if !dao.IsValid() || dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("feed policy requires the founding DAO address")
	}
	if !successor.IsValid() || successor == dao || successor == chain.PackageAddress(FeedPath) {
		panic("feed policy requires a valid distinct successor")
	}
	return FeedPolicy{dao: dao, successor: successor}
}
func (p FeedPolicy) DAO() address       { return p.dao }
func (p FeedPolicy) Successor() address { return p.successor }

type FeedAction struct {
	kind      FeedActionKind
	recipient address
	subject   address
}

func (p FeedPolicy) Accept() FeedAction { return FeedAction{kind: FeedAcceptOwner} }
func (p FeedPolicy) Return() FeedAction {
	return FeedAction{kind: FeedReturnOwner, recipient: p.successor}
}
func (p FeedPolicy) AbortReturn() FeedAction {
	return FeedAction{kind: FeedAbortReturn, recipient: p.successor}
}
func (p FeedPolicy) AddModerator(who address) FeedAction {
	if who == p.dao || who == chain.PackageAddress(FeedPath) {
		panic("feed moderator must be an external account")
	}
	a := FeedAction{kind: FeedAddModerator, subject: who}
	a.Bytes()
	return a
}
func FeedRevokeModerator(who address) FeedAction {
	a := FeedAction{kind: FeedRemoveModerator, subject: who}
	a.Bytes()
	return a
}
func FeedResume() FeedAction              { return FeedAction{kind: FeedUnpause} }
func (a FeedAction) Kind() FeedActionKind { return a.kind }
func (a FeedAction) Recipient() address   { return a.recipient }
func (a FeedAction) Subject() address     { return a.subject }
func (a FeedAction) Bytes() string {
	base := "feed/v1|" + FeedPath + "|" + string(a.kind)
	switch a.kind {
	case FeedAcceptOwner, FeedUnpause:
		if a.recipient != "" || a.subject != "" {
			panic("malformed feed action")
		}
		return base
	case FeedReturnOwner, FeedAbortReturn:
		if !a.recipient.IsValid() || a.subject != "" {
			panic("malformed feed return action")
		}
		return base + "|" + string(a.recipient)
	case FeedAddModerator, FeedRemoveModerator:
		if !a.subject.IsValid() || a.recipient != "" {
			panic("invalid feed moderator action")
		}
		return base + "|" + string(a.subject)
	default:
		panic("unsupported feed action")
	}
}
func (a FeedAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	if a.kind == FeedUnpause {
		return memba_weighted_policy.Financial
	}
	return memba_weighted_policy.Critical
}

package memba_weighted_host

import "gno.land/p/samcrew/memba_weighted_policy"

// Feed moderators are explicit grants. Ownership itself can moderate, so the
// outgoing owner must not retain a separate moderator grant after handoff.
type FeedState struct {
	Owner, PendingOwner                                                address
	Paused                                                             bool
	ModeratorCount                                                     int
	OwnerModerator, DAOModerator, SuccessorModerator, SubjectModerator bool
}
type feedProposal struct {
	action FeedAction
	before FeedState
}

func feedCommitment(a FeedAction, s FeedState) string {
	return a.Bytes() + "|before|" + feedStateJSON(s)
}
func (h *Host) validateFeedAuthority(s FeedState) {
	if h.feedPolicy == nil {
		panic("feed actions are not configured")
	}
	if !s.Owner.IsValid() || (s.PendingOwner != "" && !s.PendingOwner.IsValid()) {
		panic("invalid feed authority pre-state")
	}
	if s.ModeratorCount < 0 {
		panic("invalid feed moderator count")
	}
}
func (h *Host) validateFeed(a FeedAction, s FeedState) {
	h.validateFeedAuthority(s)
	a.Bytes()
	p := h.feedPolicy
	if a.Subject() == "" && s.SubjectModerator {
		panic("unexpected feed subject pre-state")
	}
	if a.Kind() == FeedAcceptOwner {
		if s.Owner == p.DAO() || s.PendingOwner != p.DAO() || s.OwnerModerator {
			panic("DAO is not pending feed owner or previous owner retains moderation")
		}
		return
	}
	if s.Owner != p.DAO() {
		panic("DAO is not feed owner")
	}
	if a.Kind() == FeedAbortReturn {
		if a.Recipient() != p.Successor() || s.PendingOwner != p.Successor() {
			panic("feed return does not match policy")
		}
		return
	}
	if s.PendingOwner != "" {
		panic("feed authority transfer is pending")
	}
	switch a.Kind() {
	case FeedReturnOwner:
		if a.Recipient() != p.Successor() || s.DAOModerator {
			panic("feed successor mismatch or DAO retains moderation")
		}
	case FeedAddModerator:
		p.AddModerator(a.Subject())
		if s.SubjectModerator {
			panic("feed moderator grant is a no-op")
		}
	case FeedRemoveModerator:
		if !s.SubjectModerator {
			panic("feed moderator removal is a no-op")
		}
	case FeedUnpause:
		if !s.Paused {
			panic("feed unpause is a no-op")
		}
	default:
		panic("unsupported feed action")
	}
}
func (h *Host) ProposeFeed(a FeedAction, s FeedState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateFeed(a, s)
	p := &roleProposal{proposer: who, feed: &feedProposal{action: a, before: s}}
	p.ballot = h.policy.NewProposal(a.Category(), feedCommitment(a, s))
	h.addProposal(p)
	return uint64(len(h.proposals))
}
func (h *Host) invalidateFeedPeers(cause string, id uint64) {
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(cause, id, FeedPath)
}
func (h *Host) ConsumeFeed(id uint64, s FeedState, rlm realm) FeedAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.feed == nil {
		panic("proposal is not a feed action")
	}
	h.validateFeed(p.feed.action, s)
	p.ballot.Consume(feedCommitment(p.feed.action, s))
	h.invalidateFeedPeers(InvalidatedByExecution, id)
	return p.feed.action
}
func (h *Host) PrepareFeedEmergencyPause(s FeedState, rlm realm) {
	assertCaller(h, rlm)
	h.validateFeedAuthority(s)
	if s.Owner != h.feedPolicy.DAO() || s.Paused || s.SubjectModerator {
		panic("feed emergency pause unavailable")
	}
	h.invalidateFeedPeers(InvalidatedByPause, 0)
}

