}

// Package memba_weighted_host hosts the founding policy's governed role actions.
// This source-only component is not the current memba_dao and grants no external
// application authority. The owning realm must keep its Host private.
package memba_weighted_host

import (
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/samcrew/memba_weighted_policy"
)

type Role string

const (
	Admin   Role = "admin"
	Finance Role = "finance"
)

// Seat is copied at construction. Founder/core-developer voting eligibility is
// independent from these operational role labels; all members may execute.
type Seat struct {
	Member  memba_weighted_policy.Member
	Admin   bool
	Finance bool
}

type roleProposal struct {
	feedback    *feedbackProposal
	channels    *channelsProposal
	feed        *feedProposal
	badges      *badgesProposal
	escrow      *escrowProposal
	appstore    *appstoreProposal
	arcade      *arcadeProposal
	quest       *questProposal
	reviews     *reviewsProposal
	market      *marketProposal
	recovery    bool
	personID    string
	replacement address
	proposer    address
	target      address
	role        Role
	grant       bool
	ballot      *memba_weighted_policy.Proposal
	// roster indexes Host.rosters: the electorate frozen at creation. choices
	// and votedAt mirror each seat's current ballot and the height it was cast;
	// they are written only by Host.Vote, after the policy accepted the vote.
	roster  int
	choices [7]memba_weighted_policy.Vote
	votedAt [7]int64
	// epoch is len(Host.invalidations) at creation: the first reconfiguration
	// recorded after it is the one that invalidated this proposal.
	epoch int
}

// Invalidation causes recorded on every policy reconfiguration.
const (
	InvalidatedByExecution = "superseded-execution"
	InvalidatedByPause     = "pause"
)

// invalidation records one policy reconfiguration: every proposal open at that
// moment, other than the one executed, stopped accepting votes and execution.
type invalidation struct {
	height   int64
	at       time.Time
	cause    string
	proposal uint64
	target   string
}

type Host struct {
	feedbackPolicy *FeedbackPolicy
	channelsPolicy *ChannelsPolicy
	feedPolicy     *FeedPolicy
	badgesPolicy   *BadgesPolicy
	escrowPolicy   *EscrowPolicy
	appstorePolicy *AppstorePolicy
	arcadePolicy   *ArcadePolicy
	questPolicy    *QuestPolicy
	reviewsPolicy  *ReviewsPolicy
	marketPolicy   *MarketPolicy
	path           string
	seats          [7]Seat
	policy         *memba_weighted_policy.Policy
	proposals      []*roleProposal
	// rosters holds every distinct electorate, oldest first. A new entry is
	// appended only when a recovery changes a seat address.
	rosters [][7]address
	// invalidations mirrors the policy generation: one record per Reconfigure.
	invalidations []invalidation
}

// New must run inside the owning realm's init with its own live realm value.
// No realm value is persisted; each mutation requires a fresh live frame.
func New(seats []Seat, rlm realm) *Host {
	if !rlm.IsCurrent() || !strings.HasPrefix(rlm.PkgPath(), "gno.land/r/") {
		panic("host requires its owning live realm")
	}
	members := []memba_weighted_policy.Member{}
	admins := 0
	for _, seat := range seats {
		members = append(members, seat.Member)
		if seat.Admin {
			admins++
		}
	}
	policy := memba_weighted_policy.New(members)
	if admins == 0 {
		panic("host requires an admin")
	}
	h := &Host{path: rlm.PkgPath(), policy: policy}
	for i, seat := range seats {
		h.seats[i] = seat
	}
	h.snapshotRoster()
	return h
}

func (h *Host) snapshotRoster() {
	var roster [7]address
	for i, seat := range h.seats {
		roster[i] = seat.Member.Address
	}
	h.rosters = append(h.rosters, roster)
}

// addProposal freezes the current electorate on the proposal and stores it.
// Every Propose* path goes through here, so ballots always have a snapshot.
func (h *Host) addProposal(p *roleProposal) {
	p.roster = len(h.rosters) - 1
	p.epoch = len(h.invalidations)
	h.proposals = append(h.proposals, p)
}

// recordInvalidation must follow every policy Reconfigure. It records why the
// open proposals stopped; it never decides which ones stop.
func (h *Host) recordInvalidation(cause string, id uint64, target string) {
	h.invalidations = append(h.invalidations, invalidation{height: runtime.ChainHeight(), at: time.Now(), cause: cause, proposal: id, target: target})
}

// ballotsQualified recomputes the policy threshold from the mirrored ballots.
// Ballots cannot change after a proposal closes or is invalidated, so this is
// the qualification the proposal had at that moment.
func (h *Host) ballotsQualified(p *roleProposal, category memba_weighted_policy.Category) bool {
	weight, people, developers := 0, 0, 0
	for i, vote := range p.choices {
		if vote != memba_weighted_policy.Yes {
			continue
		}
		people++
		weight++
		if h.seats[i].Member.Founder {
			weight++
		} else {
			developers++
		}
	}
	switch category {
	case memba_weighted_policy.Routine:
		return weight >= 3 && people >= 2
	case memba_weighted_policy.Financial:
		return weight >= 5 && people >= 3
	default:
		return weight >= 6 && people >= 4 || developers >= 5
	}
}

func (h *Host) memberIndex(who address) int {
	for i, seat := range h.seats {
		if seat.Member.Address == who {
			return i
		}
	}
	return -1
}

// Require both the owning path and its currently executing frame. A callee
// holding a previous DAO frame may not donate it back for authentication.
func assertCaller(h *Host, rlm realm) address {
	if rlm.PkgPath() != h.path || !rlm.IsCurrent() {
		panic("host realm mismatch")
	}
	who := rlm.Previous().Address()
	if !who.IsValid() || h.memberIndex(who) < 0 {
		panic("caller is not a member")
	}
	return who
}

func (h *Host) HasRole(who address, role Role) bool {
	i := h.memberIndex(who)
	if i < 0 {
		return false
	}
	switch role {
	case Admin:
		return h.seats[i].Admin
	case Finance:
		return h.seats[i].Finance
	default:
		return false
	}
}

func (h *Host) validateRoleChange(target address, role Role, grant bool) {
	if h.memberIndex(target) < 0 {
		panic("role target is not a member")
	}
	if role != Admin && role != Finance {
		panic("unsupported role")
	}
	if h.HasRole(target, role) == grant {
		panic("role change is a no-op")
	}
	if role == Admin && !grant {
		admins := 0
		for _, seat := range h.seats {
			if seat.Admin {
				admins++
			}
		}
		if admins <= 1 {
			panic("cannot remove last admin")
		}
	}
}

// Every role change is critical. The proposer cannot select a lower category,
// inject a callback or substitute the target/role/grant after voting begins.
func (h *Host) ProposeRole(target address, role Role, grant bool, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateRoleChange(target, role, grant)
	p := &roleProposal{proposer: who, target: target, role: role, grant: grant}
	p.ballot = h.policy.NewProposal(memba_weighted_policy.Critical, actionBytes(p))
	h.addProposal(p)
	return uint64(len(h.proposals))
}

// Recovery replaces one person's key, never their identity, weight or roles.
func (h *Host) validateRecovery(personID string, target, replacement address) {
	i := h.memberIndex(target)
	if i < 0 || h.seats[i].Member.PersonID != personID {
		panic("recovery seat does not match")
	}
	if !replacement.IsValid() || h.memberIndex(replacement) >= 0 {
		panic("replacement must be a valid unused address")
	}
}

func (h *Host) ProposeRecovery(personID string, target, replacement address, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateRecovery(personID, target, replacement)
	p := &roleProposal{proposer: who, recovery: true, personID: personID, target: target, replacement: replacement}
	p.ballot = h.policy.NewProposal(memba_weighted_policy.Critical, actionBytes(p))
	h.addProposal(p)
	return uint64(len(h.proposals))
}

func actionBytes(p *roleProposal) string {
	if p.recovery {
		// Length-prefix the unrestricted human ID to make the commitment unambiguous.
		return "recover/v1|" + strconv.Itoa(len(p.personID)) + ":" + p.personID + "|" + string(p.target) + "|" + string(p.replacement)
	}
	// Address and role domains are validated and contain no delimiter.
	return "role/v1|" + string(p.target) + "|" + string(p.role) + "|" + strconv.FormatBool(p.grant)
}

func (h *Host) proposal(id uint64) *roleProposal {
	if id == 0 || id > uint64(len(h.proposals)) {
		panic("proposal not found")
	}
	return h.proposals[id-1]
}

func (h *Host) Vote(id uint64, vote memba_weighted_policy.Vote, rlm realm) {
	who := assertCaller(h, rlm)
	p := h.proposal(id)
	p.ballot.Vote(who, vote)
	// The policy accepted the ballot, so the proposal is active and its frozen
	// electorate is the current roster. A repeated identical ballot is a no-op
	// in the policy and keeps its original height here.
	i := rosterIndex(h.rosters[p.roster], who)
	if i < 0 {
		panic("voter is not in the proposal electorate")
	}
	if p.choices[i] != vote {
		p.choices[i] = vote
		p.votedAt[i] = runtime.ChainHeight()
	}
}

func rosterIndex(roster [7]address, who address) int {
	for i, a := range roster {
		if a == who {
			return i
		}
	}
	return -1
}

func (h *Host) Execute(id uint64, rlm realm) {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.feedback != nil {
		panic("feedback action requires target adapter")
	}
	if p.channels != nil {
		panic("channels action requires target adapter")
	}
	if p.feed != nil {
		panic("feed action requires target adapter")
	}
	if p.badges != nil {
		panic("badges action requires target adapter")
	}
	if p.escrow != nil {
		panic("escrow action requires target adapter")
	}
	if p.appstore != nil {
		panic("appstore action requires target adapter")
	}
	if p.arcade != nil {
		panic("arcade action requires target adapter")
	}
	if p.quest != nil {
		panic("quest action requires target adapter")
	}
	if p.reviews != nil {
		panic("reviews action requires target adapter")
	}
	if p.market != nil {
		panic("market action requires target adapter")
	}
	if p.recovery {
		h.validateRecovery(p.personID, p.target, p.replacement)
	} else {
		h.validateRoleChange(p.target, p.role, p.grant)
	}
	p.ballot.Consume(actionBytes(p))
	i := h.memberIndex(p.target)
	if p.recovery {
		h.seats[i].Member.Address = p.replacement
		h.snapshotRoster()
	} else if p.role == Admin {
		h.seats[i].Admin = p.grant
	} else {
		h.seats[i].Finance = p.grant
	}
	// Any changed authority invalidates all outstanding authorizations. Roles
	// do not alter the approved weights or the independent developer route.
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(InvalidatedByExecution, id, "")
}

// Views contain copied values only, never pointers to policy, ballots or seats.
type ProposalView struct {
	Feedback       bool
	FeedbackAction FeedbackAction
	FeedbackBefore FeedbackState
	Channels       bool
	ChannelsAction ChannelsAction
	ChannelsBefore ChannelsState
	Feed           bool
	FeedAction     FeedAction
	FeedBefore     FeedState
	Badges         bool
	BadgesAction   BadgesAction
	BadgesBefore   BadgesState
	Escrow         bool
	EscrowAction   EscrowAction
	EscrowBefore   EscrowState
	Appstore       bool
	AppstoreAction AppstoreAction
	AppstoreBefore AppstoreState
	Arcade         bool
	ArcadeAction   ArcadeAction
	ArcadeBefore   ArcadeState
	Quest          bool
	QuestAction    QuestAction
	QuestBefore    QuestState
	Reviews        bool
	ReviewsAction  ReviewsAction
	ReviewsBefore  ReviewsState
	Market         bool
	MarketAction   MarketAction
	MarketBefore   MarketState
	Recovery       bool
	PersonID       string
	Replacement    address
	ID             uint64
	Proposer       address
	Target         address
	Role           Role
	Grant          bool
	State          memba_weighted_policy.State
	// Invalidation is set only for an INVALIDATED proposal. A proposal whose
	// vote had already closed without qualifying stays EXPIRED instead.
	Invalidated          bool
	InvalidationCause    string
	InvalidationHeight   int64
	InvalidationProposal uint64
	InvalidationTarget   string
	ExpiredBeforeInvalidation bool
}

func (h *Host) Proposal(id uint64) ProposalView {
	v := h.proposalView(id)
	p := h.proposal(id)
	s := v.State
	if s.Invalidated && !s.Consumed && p.epoch < len(h.invalidations) {
		rec := h.invalidations[p.epoch]
		if !rec.at.Before(s.VotingDeadline) && !h.ballotsQualified(p, s.Category) {
			v.ExpiredBeforeInvalidation = true
		} else {
			v.Invalidated = true
			v.InvalidationCause = rec.cause
			v.InvalidationHeight = rec.height
			v.InvalidationProposal = rec.proposal
			v.InvalidationTarget = rec.target
		}
	}
	return v
}

func (h *Host) proposalView(id uint64) ProposalView {
	p := h.proposal(id)
	if p.feedback != nil {
		return ProposalView{Feedback: true, FeedbackAction: p.feedback.action, FeedbackBefore: p.feedback.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.channels != nil {
		return ProposalView{Channels: true, ChannelsAction: p.channels.action, ChannelsBefore: p.channels.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.feed != nil {
		return ProposalView{Feed: true, FeedAction: p.feed.action, FeedBefore: p.feed.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.badges != nil {
		return ProposalView{Badges: true, BadgesAction: p.badges.action, BadgesBefore: p.badges.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.escrow != nil {
		return ProposalView{Escrow: true, EscrowAction: p.escrow.action, EscrowBefore: p.escrow.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.appstore != nil {
		return ProposalView{Appstore: true, AppstoreAction: p.appstore.action, AppstoreBefore: p.appstore.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.arcade != nil {
		return ProposalView{Arcade: true, ArcadeAction: p.arcade.action, ArcadeBefore: p.arcade.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.quest != nil {
		return ProposalView{Quest: true, QuestAction: p.quest.action, QuestBefore: p.quest.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.reviews != nil {
		return ProposalView{Reviews: true, ReviewsAction: p.reviews.action, ReviewsBefore: p.reviews.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	if p.market != nil {
		return ProposalView{Market: true, MarketAction: p.market.action, MarketBefore: p.market.before, ID: id, Proposer: p.proposer, State: p.ballot.State()}
	}
	return ProposalView{Recovery: p.recovery, PersonID: p.personID, Replacement: p.replacement, ID: id, Proposer: p.proposer, Target: p.target, Role: p.role, Grant: p.grant, State: p.ballot.State()}
}

func (h *Host) Members() []Seat {
	out := []Seat{}
	for _, seat := range h.seats {
		out = append(out, seat)
	}
	return out
}

func (h *Host) ProposalCount() uint64 { return uint64(len(h.proposals)) }

package memba_weighted_host

import (
	"strconv"

	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
)

// MarketConfigPath is the sole target of this source-only typed action model.
// These values do not dispatch an action or grant the host application authority.
const MarketConfigPath = "gno.land/r/samcrew/memba_market_config"

type MarketLane string

const (
	MarketNFT     MarketLane = "nft"
	MarketService MarketLane = "service"
	MarketToken   MarketLane = "token"
)

type MarketActionKind string

const (
	MarketAcceptAdmin  MarketActionKind = "accept-admin"
	MarketSetFee       MarketActionKind = "set-fee"
	MarketSetTreasury  MarketActionKind = "set-treasury"
	MarketReturnAdmin  MarketActionKind = "return-admin"
	MarketAbortReturn MarketActionKind = "abort-return"
)

// MarketPolicy contains only addresses separately approved for a generated DAO
// candidate. The generator requires explicit inputs and binds fixed-target
// dispatch. No address here is inferred from an old testnet literal.
type MarketPolicy struct {
	dao       address
	treasury  address
	successor address
}

func NewMarketPolicy(dao, treasury, successor address) MarketPolicy {
	target := chain.PackageAddress(MarketConfigPath)
	if !dao.IsValid() || dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("market policy requires the founding DAO address")
	}
	if !treasury.IsValid() || treasury == target || treasury == dao {
		panic("market policy requires a valid external treasury")
	}
	if !successor.IsValid() || successor == dao || successor == target {
		panic("market policy requires a valid distinct successor")
	}
	return MarketPolicy{dao: dao, treasury: treasury, successor: successor}
}

func (p MarketPolicy) DAO() address       { return p.dao }
func (p MarketPolicy) Treasury() address  { return p.treasury }
func (p MarketPolicy) Successor() address { return p.successor }

// MarketAction is a closed value, not a callback, method name or free-form
// payload. Its private fields are frozen into the commitment returned by Bytes.
type MarketAction struct {
	kind      MarketActionKind
	lane      MarketLane
	bps       int64
	recipient address
}

func MarketAccept() MarketAction { return MarketAction{kind: MarketAcceptAdmin} }

func MarketFee(lane MarketLane, bps int64) MarketAction {
	if lane != MarketNFT && lane != MarketService && lane != MarketToken {
		panic("unsupported market fee lane")
	}
	if bps < 0 || bps > 500 {
		panic("market fee out of range")
	}
	return MarketAction{kind: MarketSetFee, lane: lane, bps: bps}
}

func (p MarketPolicy) SetTreasury() MarketAction {
	return MarketAction{kind: MarketSetTreasury, recipient: p.treasury}
}

func (p MarketPolicy) ReturnAdmin() MarketAction {
	return MarketAction{kind: MarketReturnAdmin, recipient: p.successor}
}

func (p MarketPolicy) AbortReturn() MarketAction {
	return MarketAction{kind: MarketAbortReturn, recipient: p.successor}
}

func (a MarketAction) Kind() MarketActionKind { return a.kind }
func (a MarketAction) Lane() MarketLane       { return a.lane }
func (a MarketAction) BPS() int64             { return a.bps }
func (a MarketAction) Recipient() address     { return a.recipient }

func (a MarketAction) Category() memba_weighted_policy.Category {
	// Refuse zero-value or malformed actions before returning an authorization
	// category, including values created from a zero-value MarketPolicy.
	a.Bytes()
	switch a.kind {
	case MarketSetFee, MarketSetTreasury:
		return memba_weighted_policy.Financial
	case MarketAcceptAdmin, MarketReturnAdmin, MarketAbortReturn:
		return memba_weighted_policy.Critical
	default:
		panic("unsupported market action")
	}
}

// Bytes commits the target path, operation, category-relevant arguments and
// recipient. There are no user-supplied delimiters in these closed domains.
func (a MarketAction) Bytes() string {
	base := "market-config/v1|" + MarketConfigPath + "|" + string(a.kind)
	switch a.kind {
	case MarketAcceptAdmin:
		if a.lane != "" || a.bps != 0 || a.recipient != "" {
			panic("malformed market accept action")
		}
		return base
	case MarketSetFee:
		if (a.lane != MarketNFT && a.lane != MarketService && a.lane != MarketToken) || a.bps < 0 || a.bps > 500 || a.recipient != "" {
			panic("malformed market fee action")
		}
		return base + "|" + string(a.lane) + "|" + strconv.FormatInt(a.bps, 10)
	case MarketSetTreasury, MarketReturnAdmin, MarketAbortReturn:
		if a.lane != "" || a.bps != 0 || !a.recipient.IsValid() {
			panic("malformed market recipient action")
		}
		return base + "|" + string(a.recipient)
	default:
		panic("unsupported market action")
	}
}

package memba_weighted_host

import (
	"gno.land/p/samcrew/memba_weighted_policy"
	"strconv"
)

// MarketState is copied from the fixed target by the owning realm adapter.
// BPS is read only for a fee action; other actions commit zero in that field.
type MarketState struct {
	Admin        address
	PendingAdmin address
	Treasury     address
	BPS          int64
}

type marketProposal struct {
	action MarketAction
	before MarketState
}

// NewWithMarket binds immutable destinations. Keep the Host private; the realm
// must expose only the reviewed fixed-target adapter, never ConsumeMarket.
func NewWithMarket(seats []Seat, policy MarketPolicy, rlm realm) *Host {
	policy = NewMarketPolicy(policy.DAO(), policy.Treasury(), policy.Successor())
	if rlm.Address() != policy.DAO() {
		panic("market policy DAO does not own this host")
	}
	h := New(seats, rlm)
	h.marketPolicy = &policy
	return h
}

func marketCommitment(action MarketAction, before MarketState) string {
	if !before.Admin.IsValid() || !before.Treasury.IsValid() || (before.PendingAdmin != "" && !before.PendingAdmin.IsValid()) || before.BPS < 0 || before.BPS > 500 {
		panic("invalid market pre-state")
	}
	if action.Kind() != MarketSetFee && before.BPS != 0 {
		panic("unexpected market fee pre-state")
	}
	return action.Bytes() + "|before|" + string(before.Admin) + "|" + string(before.PendingAdmin) + "|" + string(before.Treasury) + "|" + strconv.FormatInt(before.BPS, 10)
}

func (h *Host) validateMarket(action MarketAction, before MarketState) {
	if h.marketPolicy == nil {
		panic("market actions are not configured")
	}
	marketCommitment(action, before)
	p := h.marketPolicy
	if action.Kind() == MarketAcceptAdmin {
		if before.Admin == p.DAO() || before.PendingAdmin != p.DAO() {
			panic("DAO is not pending market admin")
		}
		return
	}
	if before.Admin != p.DAO() {
		panic("DAO is not market admin")
	}
	if action.Kind() == MarketAbortReturn {
		if action.Recipient() != p.Successor() || before.PendingAdmin != p.Successor() {
			panic("market return does not match policy")
		}
		return
	}
	if before.PendingAdmin != "" {
		panic("market authority transfer is pending")
	}
	switch action.Kind() {
	case MarketSetFee:
		if action.BPS() == before.BPS {
			panic("market fee change is a no-op")
		}
	case MarketSetTreasury:
		if action.Recipient() != p.Treasury() {
			panic("market treasury does not match policy")
		}
		if before.Treasury == p.Treasury() {
			panic("market treasury change is a no-op")
		}
	case MarketReturnAdmin:
		if action.Recipient() != p.Successor() {
			panic("market successor does not match policy")
		}
	default:
		panic("unsupported market action")
	}
}

func (h *Host) ProposeMarket(action MarketAction, before MarketState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateMarket(action, before)
	p := &roleProposal{proposer: who, market: &marketProposal{action: action, before: before}}
	p.ballot = h.policy.NewProposal(action.Category(), marketCommitment(action, before))
	h.addProposal(p)
	return uint64(len(h.proposals))
}

// ConsumeMarket is for the owning realm's fixed adapter only. It checks the
// fresh target state and consumes authorization BEFORE crossing. No recovery
// is permitted in that adapter: a target panic must abort the transaction.
func (h *Host) ConsumeMarket(id uint64, before MarketState, rlm realm) MarketAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.market == nil {
		panic("proposal is not a market action")
	}
	h.validateMarket(p.market.action, before)
	p.ballot.Consume(marketCommitment(p.market.action, before))
	// A successful application action invalidates all other authorizations.
	// An old approval cannot revive after a return/reaccept or intervening fee
	// change. The realm lets dispatch failure abort this mutation too.
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(InvalidatedByExecution, id, MarketConfigPath)
	return p.market.action
}

package memba_weighted_host

import (
	"chain"
	"encoding/hex"
	"gno.land/p/samcrew/memba_weighted_policy"
)

const QuestPath = "gno.land/r/samcrew/memba_quest_attestation_v1"

type QuestActionKind string

const (
	QuestAcceptOwner QuestActionKind = "accept-owner"
	QuestSetSigner   QuestActionKind = "set-signer"
	QuestReturnOwner QuestActionKind = "return-owner"
	QuestAbortReturn QuestActionKind = "abort-return"
)

type QuestPolicy struct{ dao, successor address }

func NewQuestPolicy(dao, successor address) QuestPolicy {
	if !dao.IsValid() || dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("quest policy requires the founding DAO address")
	}
	if !successor.IsValid() || successor == dao || successor == chain.PackageAddress(QuestPath) {
		panic("quest policy requires a valid distinct successor")
	}
	return QuestPolicy{dao: dao, successor: successor}
}
func (p QuestPolicy) DAO() address       { return p.dao }
func (p QuestPolicy) Successor() address { return p.successor }

type QuestAction struct {
	kind      QuestActionKind
	key       string
	recipient address
}

func (p QuestPolicy) Accept() QuestAction { return QuestAction{kind: QuestAcceptOwner} }
func (p QuestPolicy) Return() QuestAction {
	return QuestAction{kind: QuestReturnOwner, recipient: p.successor}
}
func (p QuestPolicy) AbortReturn() QuestAction {
	return QuestAction{kind: QuestAbortReturn, recipient: p.successor}
}
func QuestSigner(key string) QuestAction {
	a := QuestAction{kind: QuestSetSigner, key: key}
	a.Bytes()
	return a
}
func (a QuestAction) Kind() QuestActionKind { return a.kind }
func (a QuestAction) Key() string           { return a.key }
func (a QuestAction) Recipient() address    { return a.recipient }
func canonicalQuestKey(key string) bool {
	if len(key) != 64 {
		return false
	}
	decoded, err := hex.DecodeString(key)
	return err == nil && len(decoded) == 32 && hex.EncodeToString(decoded) == key
}
func (a QuestAction) Bytes() string {
	base := "quest/v1|" + QuestPath + "|" + string(a.kind)
	switch a.kind {
	case QuestAcceptOwner:
		if a.key != "" || a.recipient != "" {
			panic("malformed quest accept action")
		}
		return base
	case QuestSetSigner:
		if !canonicalQuestKey(a.key) || a.recipient != "" {
			panic("quest signer requires canonical 32-byte hex")
		}
		return base + "|" + a.key
	case QuestReturnOwner, QuestAbortReturn:
		if a.key != "" || !a.recipient.IsValid() {
			panic("malformed quest return action")
		}
		return base + "|" + string(a.recipient)
	default:
		panic("unsupported quest action")
	}
}
func (a QuestAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	// Replacing the voucher-issuing key transfers attestation authority.
	// It cannot be disguised as a routine content change.
	return memba_weighted_policy.Critical
}

package memba_weighted_host

import "gno.land/p/samcrew/memba_weighted_policy"

// ApplicationPolicies is copied and validated by construction. No policy can
// subsequently be attached or changed on an existing host.
type ApplicationPolicies struct {
	Feedback FeedbackPolicy
	Channels ChannelsPolicy
	Feed     FeedPolicy
	Badges   BadgesPolicy
	Escrow   EscrowPolicy
	Appstore AppstorePolicy
	Arcade   ArcadePolicy
	Market   MarketPolicy
	Reviews  ReviewsPolicy
	Quest    QuestPolicy
}

func NewWithApplications(seats []Seat, policies ApplicationPolicies, rlm realm) *Host {
	h := New(seats, rlm)
	if policies.Market != (MarketPolicy{}) {
		h = NewWithMarket(seats, policies.Market, rlm)
	}
	if policies.Reviews != (ReviewsPolicy{}) {
		h = attachReviews(h, policies.Reviews, rlm)
	}
	if policies.Quest != (QuestPolicy{}) {
		p := NewQuestPolicy(policies.Quest.DAO(), policies.Quest.Successor())
		if rlm.Address() != p.DAO() {
			panic("quest policy DAO does not own this host")
		}
		h.questPolicy = &p
	}
	if policies.Arcade != (ArcadePolicy{}) {
		p := NewArcadePolicy(policies.Arcade.DAO(), policies.Arcade.Successor())
		if rlm.Address() != p.DAO() {
			panic("arcade policy DAO does not own this host")
		}
		h.arcadePolicy = &p
	}
	if policies.Appstore != (AppstorePolicy{}) {
		p := NewAppstorePolicy(policies.Appstore.DAO(), policies.Appstore.Successor(), policies.Appstore.Treasury())
		if rlm.Address() != p.DAO() {
			panic("appstore policy DAO does not own this host")
		}
		h.appstorePolicy = &p
	}
	if policies.Escrow != (EscrowPolicy{}) {
		p := NewEscrowPolicy(policies.Escrow.DAO(), policies.Escrow.Successor())
		if rlm.Address() != p.DAO() {
			panic("escrow policy DAO does not own this host")
		}
		h.escrowPolicy = &p
	}
	if policies.Badges != (BadgesPolicy{}) {
		p := NewBadgesPolicy(policies.Badges.DAO(), policies.Badges.Successor())
		if rlm.Address() != p.DAO() {
			panic("badges policy DAO does not own this host")
		}
		h.badgesPolicy = &p
	}
	if policies.Feed != (FeedPolicy{}) {
		p := NewFeedPolicy(policies.Feed.DAO(), policies.Feed.Successor())
		if rlm.Address() != p.DAO() {
			panic("feed policy DAO does not own this host")
		}
		h.feedPolicy = &p
	}
	if policies.Channels != (ChannelsPolicy{}) {
		p := NewChannelsPolicy(policies.Channels.DAO(), policies.Channels.Successor())
		if rlm.Address() != p.DAO() {
			panic("channels policy DAO does not own this host")
		}
		h.channelsPolicy = &p
	}
	if policies.Feedback != (FeedbackPolicy{}) {
		p := NewFeedbackPolicy(policies.Feedback.DAO(), policies.Feedback.Successor())
		if rlm.Address() != p.DAO() {
			panic("feedback policy DAO does not own this host")
		}
		h.feedbackPolicy = &p
	}
	return h
}

type QuestState struct {
	Owner, PendingOwner address
	Signer              string
}
type questProposal struct {
	action QuestAction
	before QuestState
}

func questCommitment(a QuestAction, before QuestState) string {
	return a.Bytes() + "|before|" + questStateJSON(before)
}
func (h *Host) validateQuest(a QuestAction, before QuestState) {
	if h.questPolicy == nil {
		panic("quest actions are not configured")
	}
	a.Bytes()
	p := h.questPolicy
	if !before.Owner.IsValid() || (before.PendingOwner != "" && !before.PendingOwner.IsValid()) || (before.Signer != "" && !canonicalQuestKey(before.Signer)) {
		panic("invalid quest pre-state")
	}
	if a.Kind() == QuestAcceptOwner {
		if before.Owner == p.DAO() || before.PendingOwner != p.DAO() {
			panic("DAO is not pending quest owner")
		}
		return
	}
	if before.Owner != p.DAO() {
		panic("DAO is not quest owner")
	}
	if a.Kind() == QuestAbortReturn {
		if a.Recipient() != p.Successor() || before.PendingOwner != p.Successor() {
			panic("quest return does not match policy")
		}
		return
	}
	if before.PendingOwner != "" {
		panic("quest authority transfer is pending")
	}
	switch a.Kind() {
	case QuestSetSigner:
		if before.Signer == a.Key() {
			panic("quest signer change is a no-op")
		}
	case QuestReturnOwner:
		if a.Recipient() != p.Successor() {
			panic("quest successor does not match policy")
		}
	default:
		panic("unsupported quest action")
	}
}
func (h *Host) ProposeQuest(a QuestAction, before QuestState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateQuest(a, before)
	p := &roleProposal{proposer: who, quest: &questProposal{action: a, before: before}}
	p.ballot = h.policy.NewProposal(a.Category(), questCommitment(a, before))
	h.addProposal(p)
	return uint64(len(h.proposals))
}
func (h *Host) ConsumeQuest(id uint64, before QuestState, rlm realm) QuestAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.quest == nil {
		panic("proposal is not a quest action")
	}
	h.validateQuest(p.quest.action, before)
	p.ballot.Consume(questCommitment(p.quest.action, before))
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(InvalidatedByExecution, id, QuestPath)
	return p.quest.action
}

package memba_weighted_host

func (h *Host) questConfigJSON() string {
	if h.questPolicy == nil {
		return ""
	}
	return `,"questPolicy":{"target":` + quoteJSON(QuestPath) + `,"successor":` + quoteJSON(string(h.questPolicy.Successor())) + `,"signerCategory":"critical","returnStagesOnly":true,"invalidatesOtherProposals":true}`
}
func questStateJSON(s QuestState) string {
	return `{"owner":` + quoteJSON(string(s.Owner)) + `,"pendingOwner":` + quoteJSON(string(s.PendingOwner)) + `,"signer":` + quoteJSON(s.Signer) + `}`
}
func questActionJSON(a QuestAction, s QuestState) string {
	return `{"type":"quest","target":` + quoteJSON(QuestPath) + `,"operation":` + quoteJSON(string(a.Kind())) + `,"signer":` + quoteJSON(a.Key()) + `,"recipient":` + quoteJSON(string(a.Recipient())) + `,"before":` + questStateJSON(s) + `}`
}

package memba_weighted_host

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/samcrew/memba_weighted_policy"
)

const ReadSchema = "memba-weighted-host/v2"
const MaxProposalPage = 50

func (h *Host) readSchema() string {
	if h.feedbackPolicy != nil {
		return "memba-weighted-host/v12"
	}
	if h.channelsPolicy != nil {
		return "memba-weighted-host/v11"
	}
	if h.feedPolicy != nil {
		return "memba-weighted-host/v10"
	}
	if h.badgesPolicy != nil {
		return "memba-weighted-host/v9"
	}
	if h.escrowPolicy != nil {
		return "memba-weighted-host/v8"
	}
	if h.appstorePolicy != nil {
		return "memba-weighted-host/v7"
	}
	if h.arcadePolicy != nil {
		return "memba-weighted-host/v6"
	}
	if h.questPolicy != nil {
		return "memba-weighted-host/v5"
	}
	if h.reviewsPolicy != nil {
		return "memba-weighted-host/v4"
	}
	if h.marketPolicy != nil {
		return "memba-weighted-host/v3"
	}
	return ReadSchema
}

func (h *Host) marketConfigJSON() string {
	if h.marketPolicy == nil {
		return ""
	}
	return `,"marketPolicy":{"target":` + quoteJSON(MarketConfigPath) + `,"treasury":` + quoteJSON(string(h.marketPolicy.Treasury())) + `,"successor":` + quoteJSON(string(h.marketPolicy.Successor())) + `,"feeCategory":"financial","treasuryCategory":"financial","returnStagesOnly":true,"invalidatesOtherProposals":true}`
}

// JSON strings use JSON escapes, not Go's \xNN/\a/\v escapes. Invalid UTF-8
// decodes as U+FFFD, matching JSON's Unicode string domain.
func quoteJSON(value string) string {
	var b strings.Builder
	b.WriteByte('"')
	const hex = "0123456789abcdef"
	for _, r := range value {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		default:
			if r < 0x20 {
				b.WriteString(`\u00`)
				b.WriteByte(hex[byte(r)>>4])
				b.WriteByte(hex[byte(r)&15])
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func timestampJSON(value time.Time) string {
	if value.IsZero() {
		return "null"
	}
	return quoteJSON(value.UTC().Format(time.RFC3339Nano))
}

// ConfigJSON describes only implemented host capabilities. Fixed founding
// thresholds are not configurable through a role action. Operational role labels
// have no additional vote or execution privilege.
func (h *Host) ConfigJSON() string {
	return `{"schema":` + quoteJSON(h.readSchema()) + `,"kind":"config","realmPath":` + quoteJSON(h.path) + `,"rosterSize":7,"totalPoints":8,"founderWeight":2,"developerWeight":1,"votingPeriodSeconds":604800,"roleChanges":{"category":"critical","weightedPoints":6,"weightedPeople":4,"weightedDelaySeconds":86400,"independentDevelopers":5,"independentDelaySeconds":259200},"mutableRoles":["admin","finance"],"capabilities":{"roleProposals":true,"memberReplacement":true,"migration":false,"treasuryExecution":false,"applicationActions":` + strconv.FormatBool(h.marketPolicy != nil || h.reviewsPolicy != nil || h.questPolicy != nil || h.arcadePolicy != nil || h.appstorePolicy != nil || h.escrowPolicy != nil || h.badgesPolicy != nil || h.feedPolicy != nil || h.channelsPolicy != nil || h.feedbackPolicy != nil) + `},"maxProposalPage":50` + h.marketConfigJSON() + h.reviewsConfigJSON() + h.questConfigJSON() + h.arcadeConfigJSON() + h.appstoreConfigJSON() + h.escrowConfigJSON() + h.badgesConfigJSON() + h.feedConfigJSON() + h.channelsConfigJSON() + h.feedbackConfigJSON() + `}`
}

func (h *Host) MembersJSON() string {
	var b strings.Builder
	b.WriteString(`{"schema":` + quoteJSON(h.readSchema()) + `,"kind":"members","members":[`)
	for i, seat := range h.seats {
		if i > 0 {
			b.WriteByte(',')
		}
		weight := 1
		if seat.Member.Founder {
			weight = 2
		}
		b.WriteString(`{"personId":` + quoteJSON(seat.Member.PersonID) + `,"address":` + quoteJSON(string(seat.Member.Address)) + `,"founder":` + strconv.FormatBool(seat.Member.Founder) + `,"weight":` + strconv.Itoa(weight) + `,"admin":` + strconv.FormatBool(seat.Admin) + `,"finance":` + strconv.FormatBool(seat.Finance) + `}`)
	}
	b.WriteString(`]}`)
	return b.String()
}

func status(s memba_weighted_policy.State) string {
	// Successful role execution also advances the configuration generation.
	// Consumed therefore takes precedence over subsequent invalidation.
	if s.Consumed {
		return "EXECUTED"
	}
	if s.Invalidated {
		return "INVALIDATED"
	}
	if s.Expired {
		return "EXPIRED"
	}
	if s.Ready {
		return "READY"
	}
	if s.Qualified {
		return "TIMELOCKED"
	}
	return "VOTING"
}

// viewStatus keeps EXPIRED sticky: a proposal whose voting closed without
// qualifying reports EXPIRED even after a later reconfiguration.
func viewStatus(v ProposalView) string {
	if !v.State.Consumed && v.ExpiredBeforeInvalidation {
		return "EXPIRED"
	}
	return status(v.State)
}

// invalidationJSON is null unless the status is INVALIDATED. cause is
// "superseded-execution" (proposalId is the executed proposal) or "pause"
// (proposalId is null). target is the application realm, or null for a
// role or recovery execution.
func invalidationJSON(v ProposalView) string {
	if !v.Invalidated {
		return "null"
	}
	id, target := "null", "null"
	if v.InvalidationProposal != 0 {
		id = quoteJSON(strconv.FormatUint(v.InvalidationProposal, 10))
	}
	if v.InvalidationTarget != "" {
		target = quoteJSON(v.InvalidationTarget)
	}
	return `{"cause":` + quoteJSON(v.InvalidationCause) + `,"height":` + quoteJSON(strconv.FormatInt(v.InvalidationHeight, 10)) + `,"proposalId":` + id + `,"target":` + target + `}`
}

// Terminal policy states clear current tallies; they are not evidence of zero
// historical votes. Do not invent a receipt the host did not retain.
func tallyJSON(n int, s memba_weighted_policy.State) string {
	if s.Consumed || s.Invalidated {
		return "null"
	}
	return strconv.Itoa(n)
}

func proposalActionJSON(v ProposalView) string {
	if v.Feedback {
		return feedbackActionJSON(v.FeedbackAction, v.FeedbackBefore)
	}
	if v.Channels {
		return channelsActionJSON(v.ChannelsAction, v.ChannelsBefore)
	}
	if v.Feed {
		return feedActionJSON(v.FeedAction, v.FeedBefore)
	}
	if v.Badges {
		return badgesActionJSON(v.BadgesAction, v.BadgesBefore)
	}
	if v.Escrow {
		return escrowActionJSON(v.EscrowAction, v.EscrowBefore)
	}
	if v.Appstore {
		return appstoreActionJSON(v.AppstoreAction, v.AppstoreBefore)
	}
	if v.Arcade {
		return arcadeActionJSON(v.ArcadeAction, v.ArcadeBefore)
	}
	if v.Quest {
		return questActionJSON(v.QuestAction, v.QuestBefore)
	}
	if v.Reviews {
		return reviewsActionJSON(v.ReviewsAction, v.ReviewsBefore)
	}
	if v.Market {
		a := v.MarketAction
		b := v.MarketBefore
		return `{"type":"market-config","target":` + quoteJSON(MarketConfigPath) + `,"operation":` + quoteJSON(string(a.Kind())) + `,"lane":` + quoteJSON(string(a.Lane())) + `,"bps":` + quoteJSON(strconv.FormatInt(a.BPS(), 10)) + `,"recipient":` + quoteJSON(string(a.Recipient())) + `,"before":{"admin":` + quoteJSON(string(b.Admin)) + `,"pendingAdmin":` + quoteJSON(string(b.PendingAdmin)) + `,"treasury":` + quoteJSON(string(b.Treasury)) + `,"bps":` + quoteJSON(strconv.FormatInt(b.BPS, 10)) + `}}`
	}
	if v.Recovery {
		return `{"type":"recover-member","personId":` + quoteJSON(v.PersonID) + `,"oldAddress":` + quoteJSON(string(v.Target)) + `,"newAddress":` + quoteJSON(string(v.Replacement)) + `}`
	}
	return `{"type":"set-role","target":` + quoteJSON(string(v.Target)) + `,"role":` + quoteJSON(string(v.Role)) + `,"grant":` + strconv.FormatBool(v.Grant) + `}`
}

func proposalJSON(v ProposalView) string {
	s := v.State
	return `{"id":` + quoteJSON(strconv.FormatUint(v.ID, 10)) + `,"proposer":` + quoteJSON(string(v.Proposer)) + `,"action":` + proposalActionJSON(v) + `,"category":` + quoteJSON(string(s.Category)) + `,"status":` + quoteJSON(viewStatus(v)) + `,"qualified":` + strconv.FormatBool(s.Qualified) + `,"ready":` + strconv.FormatBool(s.Ready) + `,"votingClosed":` + strconv.FormatBool(s.VotingClosed) + `,"talliesAvailable":` + strconv.FormatBool(!s.Consumed && !s.Invalidated) + `,"weightYes":` + tallyJSON(s.WeightYes, s) + `,"peopleYes":` + tallyJSON(s.PeopleYes, s) + `,"developersYes":` + tallyJSON(s.DevelopersYes, s) + `,"createdAt":` + timestampJSON(s.CreatedAt) + `,"votingDeadline":` + timestampJSON(s.VotingDeadline) + `,"weightedAfter":` + timestampJSON(s.WeightedAfter) + `,"developerAfter":` + timestampJSON(s.DeveloperAfter) + `,"invalidation":` + invalidationJSON(v) + `}`
}

func (h *Host) ProposalJSON(id uint64) string {
	return `{"schema":` + quoteJSON(h.readSchema()) + `,"kind":"proposal","proposal":` + proposalJSON(h.Proposal(id)) + `}`
}

// ProposalsJSON uses an exclusive descending ID cursor. before=0 means newest;
// a returned nextBefore remains stable when newer proposals are appended.
// IDs/cursors/counts are decimal strings so uint64 values never lose precision
// in a JavaScript client. A null cursor ends pagination, not an empty page guess.
func (h *Host) ProposalsJSON(before uint64, limit int) string {
	if limit < 1 || limit > MaxProposalPage {
		panic("invalid proposal page size")
	}
	count := h.ProposalCount()
	if before > count {
		panic("invalid proposal cursor")
	}
	id := count
	if before > 0 {
		id = before - 1
	}
	var b strings.Builder
	b.WriteString(`{"schema":` + quoteJSON(h.readSchema()) + `,"kind":"proposals","total":` + quoteJSON(strconv.FormatUint(count, 10)) + `,"proposals":[`)
	n := 0
	last := uint64(0)
	for id > 0 && n < limit {
		if n > 0 {
			b.WriteByte(',')
		}
		b.WriteString(proposalJSON(h.Proposal(id)))
		last = id
		id--
		n++
	}
	b.WriteString(`],"nextBefore":`)
	if id > 0 {
		b.WriteString(quoteJSON(strconv.FormatUint(last, 10)))
	} else {
		b.WriteString("null")
	}
	b.WriteByte('}')
	return b.String()
}

// Ballot reads. Pending pages hold at most MaxPendingPage proposals, and one
// call examines at most MaxPendingScan proposals before handing back a cursor.
const MaxPendingPage = 50
const MaxPendingScan = 200

// parseDecimalID accepts only canonical unsigned decimal strings, the same
// form every read emits, so one ID has exactly one spelling.
func parseDecimalID(value, what string) uint64 {
	n, err := strconv.ParseUint(value, 10, 64)
	if err != nil || strconv.FormatUint(n, 10) != value {
		panic("invalid " + what)
	}
	return n
}

func ballotChoiceJSON(v memba_weighted_policy.Vote) string {
	if v == "" {
		return "null"
	}
	return quoteJSON(string(v))
}

// BallotJSON reports one address's ballot on one proposal. Eligibility is the
// electorate frozen when the proposal was created, so a recovered key keeps
// its ballot on older proposals and has none on newer ones. choice is "yes",
// "no" or "abstain" (the host's three ballot values), or null with a null
// votedAtHeight when the address has not voted. Ballots stay readable after a
// proposal is executed, invalidated or expired; tallies do not.
func (h *Host) BallotJSON(proposalID string, voter address) string {
	id := parseDecimalID(proposalID, "proposal id")
	p := h.proposal(id)
	i := rosterIndex(h.rosters[p.roster], voter)
	choice, height := "null", "null"
	if i >= 0 && p.choices[i] != "" {
		choice = ballotChoiceJSON(p.choices[i])
		height = quoteJSON(strconv.FormatInt(p.votedAt[i], 10))
	}
	return `{"schema":` + quoteJSON(h.readSchema()) + `,"proposalId":` + quoteJSON(strconv.FormatUint(id, 10)) + `,"voter":` + quoteJSON(string(voter)) + `,"eligible":` + strconv.FormatBool(i >= 0) + `,"choice":` + choice + `,"votedAtHeight":` + height + `}`
}

// PendingVotesJSON lists, newest first, the proposals that are still open for
// voting where voter is in the frozen electorate and has not voted. before is
// an exclusive decimal cursor ("" or "0" for newest); limit is clamped to
// 1..MaxPendingPage. Executing any action invalidates every older open
// proposal, and deadlines follow creation order, so the scan stops at the first
// proposal that no longer accepts votes: nothing older can be pending. The
// scan also stops after MaxPendingScan proposals; next then resumes it. next
// is null when nothing older can be pending.
func (h *Host) PendingVotesJSON(voter address, before string, limit int) string {
	if limit < 1 {
		limit = 1
	}
	if limit > MaxPendingPage {
		limit = MaxPendingPage
	}
	count := h.ProposalCount()
	id := count
	if before != "" && before != "0" {
		cursor := parseDecimalID(before, "proposal cursor")
		if cursor > count {
			panic("invalid proposal cursor")
		}
		id = cursor - 1
	}
	var b strings.Builder
	b.WriteString(`{"schema":` + quoteJSON(h.readSchema()) + `,"voter":` + quoteJSON(string(voter)) + `,"items":[`)
	n, scanned, closed := 0, 0, false
	for id > 0 && n < limit && scanned < MaxPendingScan {
		p := h.proposals[id-1]
		s := p.ballot.State()
		if s.Consumed || s.Invalidated || s.VotingClosed {
			closed = true
			break
		}
		scanned++
		i := rosterIndex(h.rosters[p.roster], voter)
		if i >= 0 && p.choices[i] == "" {
			if n > 0 {
				b.WriteByte(',')
			}
			b.WriteString(proposalJSON(h.Proposal(id)))
			n++
		}
		id--
	}
	b.WriteString(`],"next":`)
	if closed || id == 0 {
		b.WriteString("null")
	} else {
		b.WriteString(quoteJSON(strconv.FormatUint(id+1, 10)))
	}
	b.WriteByte('}')
	return b.String()
}

package memba_weighted_host

import (
	"chain"
	"gno.land/p/samcrew/memba_weighted_policy"
	"strconv"
)

const ReviewsV1Path = "gno.land/r/samcrew/memba_reviews_v1"
const ReviewsV2Path = "gno.land/r/samcrew/memba_reviews_v2"

type ReviewsPolicy struct {
	dao       address
	target    string
	successor address
}

func NewReviewsPolicy(dao address, target string, successor address) ReviewsPolicy {
	if dao != chain.PackageAddress("gno.land/r/samcrew/memba_dao") {
		panic("reviews policy requires the founding DAO address")
	}
	if target != ReviewsV1Path && target != ReviewsV2Path {
		panic("unsupported reviews target")
	}
	if !successor.IsValid() || successor == dao || successor == chain.PackageAddress(target) {
		panic("reviews policy requires a valid distinct successor")
	}
	return ReviewsPolicy{dao: dao, target: target, successor: successor}
}
func (p ReviewsPolicy) DAO() address       { return p.dao }
func (p ReviewsPolicy) Target() string     { return p.target }
func (p ReviewsPolicy) Successor() address { return p.successor }

type ReviewsActionKind string

const (
	ReviewsAcceptModerator ReviewsActionKind = "accept-moderator"
	ReviewsReturnModerator ReviewsActionKind = "return-moderator"
	ReviewsAbortReturn     ReviewsActionKind = "abort-return"
	ReviewsHideReview      ReviewsActionKind = "hide-review"
	ReviewsHideComment     ReviewsActionKind = "hide-comment"
	ReviewsUnhide          ReviewsActionKind = "unhide"
)

type ReviewsAction struct {
	kind      ReviewsActionKind
	target    string
	id        uint64
	recipient address
}

func (p ReviewsPolicy) Accept() ReviewsAction {
	return ReviewsAction{kind: ReviewsAcceptModerator, target: p.target}
}
func (p ReviewsPolicy) Return() ReviewsAction {
	return ReviewsAction{kind: ReviewsReturnModerator, target: p.target, recipient: p.successor}
}
func (p ReviewsPolicy) AbortReturn() ReviewsAction {
	return ReviewsAction{kind: ReviewsAbortReturn, target: p.target, recipient: p.successor}
}
func (p ReviewsPolicy) HideReview(id uint64) ReviewsAction {
	return p.itemAction(ReviewsHideReview, id)
}
func (p ReviewsPolicy) HideComment(id uint64) ReviewsAction {
	return p.itemAction(ReviewsHideComment, id)
}
func (p ReviewsPolicy) Unhide(id uint64) ReviewsAction { return p.itemAction(ReviewsUnhide, id) }
func (p ReviewsPolicy) itemAction(kind ReviewsActionKind, id uint64) ReviewsAction {
	if id == 0 {
		panic("reviews item ID must be positive")
	}
	return ReviewsAction{kind: kind, target: p.target, id: id}
}
func (a ReviewsAction) Kind() ReviewsActionKind { return a.kind }
func (a ReviewsAction) Target() string          { return a.target }
func (a ReviewsAction) ID() uint64              { return a.id }
func (a ReviewsAction) Recipient() address      { return a.recipient }
func (a ReviewsAction) Category() memba_weighted_policy.Category {
	a.Bytes()
	switch a.kind {
	case ReviewsHideReview, ReviewsHideComment, ReviewsUnhide:
		return memba_weighted_policy.Routine
	default:
		return memba_weighted_policy.Critical
	}
}
func (a ReviewsAction) Bytes() string {
	if a.target != ReviewsV1Path && a.target != ReviewsV2Path {
		panic("unsupported reviews target")
	}
	switch a.kind {
	case ReviewsAcceptModerator:
		if a.id != 0 || a.recipient != "" {
			panic("malformed reviews authority action")
		}
	case ReviewsReturnModerator, ReviewsAbortReturn:
		if a.id != 0 || !a.recipient.IsValid() {
			panic("malformed reviews authority action")
		}
	case ReviewsHideReview, ReviewsHideComment, ReviewsUnhide:
		if a.id == 0 || a.recipient != "" {
			panic("malformed reviews item action")
		}
	default:
		panic("unsupported reviews action")
	}
	return "reviews/v1|" + a.target + "|" + string(a.kind) + "|" + strconv.FormatUint(a.id, 10) + "|" + string(a.recipient)
}

package memba_weighted_host

import "gno.land/p/samcrew/memba_weighted_policy"

// ReviewsItem contains copied moderation-relevant state only. Ordinary reactions
// do not invalidate moderation; content edits, deletion and visibility do.
type ReviewsItem struct {
	ID        uint64
	Review    bool
	ParentID  uint64
	Subject   string
	Author    address
	Rating    int
	BodyHash  string
	CreatedAt int64
	EditedAt  int64
	Hidden    bool
	Deleted   bool
	Flagged   bool
}
type ReviewsState struct {
	Moderator        address
	PendingModerator address
	Item             ReviewsItem
}
type reviewsProposal struct {
	action ReviewsAction
	before ReviewsState
}

func attachReviews(h *Host, policy ReviewsPolicy, rlm realm) *Host {
	policy = NewReviewsPolicy(policy.DAO(), policy.Target(), policy.Successor())
	if rlm.Address() != policy.DAO() {
		panic("reviews policy DAO does not own this host")
	}
	h.reviewsPolicy = &policy
	return h
}
func NewWithReviews(seats []Seat, policy ReviewsPolicy, rlm realm) *Host {
	return attachReviews(New(seats, rlm), policy, rlm)
}
func NewWithMarketAndReviews(seats []Seat, market MarketPolicy, reviews ReviewsPolicy, rlm realm) *Host {
	return attachReviews(NewWithMarket(seats, market, rlm), reviews, rlm)
}
func reviewsCommitment(action ReviewsAction, before ReviewsState) string {
	return action.Bytes() + "|before|" + reviewsStateJSON(before)
}
func (h *Host) validateReviews(a ReviewsAction, before ReviewsState) {
	if h.reviewsPolicy == nil {
		panic("reviews actions are not configured")
	}
	a.Bytes()
	p := h.reviewsPolicy
	if a.Target() != p.Target() {
		panic("reviews target does not match policy")
	}
	if !before.Moderator.IsValid() || (before.PendingModerator != "" && !before.PendingModerator.IsValid()) {
		panic("invalid reviews authority pre-state")
	}
	if a.ID() == 0 && before.Item != (ReviewsItem{}) {
		panic("unexpected reviews item pre-state")
	}
	if a.Kind() == ReviewsAcceptModerator {
		if before.Moderator == p.DAO() || before.PendingModerator != p.DAO() {
			panic("DAO is not pending reviews moderator")
		}
		return
	}
	if before.Moderator != p.DAO() {
		panic("DAO is not reviews moderator")
	}
	if a.Kind() == ReviewsAbortReturn {
		if a.Recipient() != p.Successor() || before.PendingModerator != p.Successor() {
			panic("reviews return does not match policy")
		}
		return
	}
	if before.PendingModerator != "" {
		panic("reviews authority transfer is pending")
	}
	if a.Kind() == ReviewsReturnModerator {
		if a.Recipient() != p.Successor() {
			panic("reviews successor does not match policy")
		}
		return
	}
	item := before.Item
	if item.ID != a.ID() || item.ID == 0 {
		panic("reviews item not found")
	}
	// Legacy v1 retains flagged-index entries after deletion. Unhide may
	// clear only such a flagged tombstone; the adapter preserves Deleted.
	if item.Deleted && !(a.Kind() == ReviewsUnhide && item.Flagged) {
		panic("reviews item is deleted")
	}
	if !item.Author.IsValid() || len(item.BodyHash) != 64 {
		panic("invalid reviews item pre-state")
	}
	if item.Review {
		if item.ParentID != 0 || item.Subject == "" || item.Rating < 1 || item.Rating > 5 {
			panic("invalid review pre-state")
		}
	} else if item.ParentID == 0 || item.Subject != "" || item.Rating != 0 {
		panic("invalid comment pre-state")
	}
	switch a.Kind() {
	case ReviewsHideReview:
		if !item.Review {
			panic("reviews item is not a review")
		}
		if item.Hidden {
			panic("reviews hide is a no-op")
		}
	case ReviewsHideComment:
		if item.Review {
			panic("reviews item is not a comment")
		}
		if item.Hidden {
			panic("reviews hide is a no-op")
		}
	case ReviewsUnhide:
		if !item.Hidden && !item.Flagged {
			panic("reviews unhide is a no-op")
		}
	default:
		panic("unsupported reviews action")
	}
}
func (h *Host) ProposeReviews(action ReviewsAction, before ReviewsState, rlm realm) uint64 {
	who := assertCaller(h, rlm)
	h.validateReviews(action, before)
	p := &roleProposal{proposer: who, reviews: &reviewsProposal{action: action, before: before}}
	p.ballot = h.policy.NewProposal(action.Category(), reviewsCommitment(action, before))
	h.addProposal(p)
	return uint64(len(h.proposals))
}

// Only the owning realm's fixed adapter may use this. Keep Host private and
// let target panics/postcondition failures abort the entire transaction.
func (h *Host) ConsumeReviews(id uint64, before ReviewsState, rlm realm) ReviewsAction {
	assertCaller(h, rlm)
	p := h.proposal(id)
	if p.reviews == nil {
		panic("proposal is not a reviews action")
	}
	h.validateReviews(p.reviews.action, before)
	p.ballot.Consume(reviewsCommitment(p.reviews.action, before))
	members := []memba_weighted_policy.Member{}
	for _, seat := range h.seats {
		members = append(members, seat.Member)
	}
	h.policy.Reconfigure(members)
	h.recordInvalidation(InvalidatedByExecution, id, h.reviewsPolicy.Target())
	return p.reviews.action
}

package memba_weighted_host

import "strconv"

func (h *Host) reviewsConfigJSON() string {
	if h.reviewsPolicy == nil {
		return ""
	}
	return `,"reviewsPolicy":{"target":` + quoteJSON(h.reviewsPolicy.Target()) + `,"successor":` + quoteJSON(string(h.reviewsPolicy.Successor())) + `,"moderationCategory":"routine","returnStagesOnly":true,"invalidatesOtherProposals":true}`
}
func reviewsItemJSON(i ReviewsItem) string {
	return `{"id":` + quoteJSON(strconv.FormatUint(i.ID, 10)) + `,"review":` + strconv.FormatBool(i.Review) + `,"parentId":` + quoteJSON(strconv.FormatUint(i.ParentID, 10)) + `,"subject":` + quoteJSON(i.Subject) + `,"author":` + quoteJSON(string(i.Author)) + `,"rating":` + quoteJSON(strconv.Itoa(i.Rating)) + `,"bodyHash":` + quoteJSON(i.BodyHash) + `,"createdAtHeight":` + quoteJSON(strconv.FormatInt(i.CreatedAt, 10)) + `,"editedAtHeight":` + quoteJSON(strconv.FormatInt(i.EditedAt, 10)) + `,"hidden":` + strconv.FormatBool(i.Hidden) + `,"deleted":` + strconv.FormatBool(i.Deleted) + `,"flagged":` + strconv.FormatBool(i.Flagged) + `}`
}
func reviewsStateJSON(s ReviewsState) string {
	return `{"moderator":` + quoteJSON(string(s.Moderator)) + `,"pendingModerator":` + quoteJSON(string(s.PendingModerator)) + `,"item":` + reviewsItemJSON(s.Item) + `}`
}
func reviewsActionJSON(a ReviewsAction, s ReviewsState) string {
	return `{"type":"reviews","target":` + quoteJSON(a.Target()) + `,"operation":` + quoteJSON(string(a.Kind())) + `,"id":` + quoteJSON(strconv.FormatUint(a.ID(), 10)) + `,"recipient":` + quoteJSON(string(a.Recipient())) + `,"before":` + reviewsStateJSON(s) + `}`
}

package memba_dao
import("strings";"gno.land/p/samcrew/memba_weighted_host";"gno.land/r/samcrew/memba_appstore_v3")
func appstoreState(a memba_weighted_host.AppstoreAction)memba_weighted_host.AppstoreState{
 owner:=memba_appstore_v3.GetOwner();s:=memba_weighted_host.AppstoreState{Owner:owner,PendingOwner:memba_appstore_v3.GetPendingOwner(),Treasury:memba_appstore_v3.GetTreasury(),Fee:memba_appstore_v3.GetRegistrationFee(),Paused:memba_appstore_v3.IsPaused(),Sealed:memba_appstore_v3.IsSeedingSealed(),OwnerCurator:memba_appstore_v3.IsCurator(string(owner)),DAOCurator:memba_appstore_v3.IsCurator(string(appstorePolicy.DAO())),SuccessorCurator:memba_appstore_v3.IsCurator(string(appstorePolicy.Successor()))}
 if a.Kind()==memba_weighted_host.AppstoreAddCurator||a.Kind()==memba_weighted_host.AppstoreRemoveCurator{s.SubjectCurator=memba_appstore_v3.IsCurator(string(a.Recipient()))}
 if a.IsListing(){l:=memba_appstore_v3.GetGovernanceListing(a.Path(),a.Kind()==memba_weighted_host.AppstoreClearFlags);s.Listing=memba_weighted_host.AppstoreListing{Exists:l.Exists,ContentHash:l.ContentHash,Status:l.Status,Reason:l.Reason,Credit:l.Credit,Flags:l.Flags,ClearKeys:l.ClearKeys}}
 return s
}
func proposeAppstore(cur realm,a memba_weighted_host.AppstoreAction)uint64{return host.ProposeAppstore(a,appstoreState(a),cur)}
func ProposeAppstoreAccept(cur realm)uint64{return proposeAppstore(cur,appstorePolicy.Accept())}
func ProposeAppstoreReturn(cur realm)uint64{return proposeAppstore(cur,appstorePolicy.Return())}
func ProposeAppstoreAbortReturn(cur realm)uint64{return proposeAppstore(cur,appstorePolicy.AbortReturn())}
